d, github.run_attempt) || '' }}${{ inputs.mode }}-${{ inputs.request_id }}\n   123\t      cancel-in-progress: false\n   124\t    steps:\n   125\t      - name: Record verification deadline origin\n   126\t        run: echo \"PALOMAR_JOB_STARTED_AT=$(date +%s)\" >> \"$GITHUB_ENV\"\n   127\t\n   128\t      - name: Validate pinned pipeline revision\n   129\t        env:\n   130\t          PIPELINE_COMMIT: ${{ inputs.pipeline_commit || github.workflow_sha }}\n   131\t        run: |\n   132\t          if [[ ! \"$PIPELINE_COMMIT\" =~ ^[0-9a-f]{40}$ ]]; then\n   133\t            echo \"pipeline_commit must be a full lowercase commit SHA\" >&2\n   134\t            exit 1\n   135\t          fi\n   136\t\n   137\t      - name: Checkout submission pipeline\n   138\t        id: checkout\n   139\t        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1\n   140\t        with:\n   141\t          repository: PalomarRegistry/PalomarSubmission\n   142\t          ref: ${{ inputs.pipeline_commit || github.workflow_sha }}\n   143\t          path: pipeline\n   144\t          persist-credentials: false\n   145\t\n   146\t      - name: Set up Python\n   147\t        uses: actions/setup-python@5fda3b95a4ea91299a34e894583c3862153e4b97 # v7.0.0\n   148\t        id: python\n   149\t        with:\n   150\t          python-version: \"3.11.10\"\n   151\t\n   152\t      - name: Set up Ruby\n   153\t        uses: ruby/setup-ruby@95ef2b042f9d7a56d8268cba8559e2842e2ad01b # v1.321.0\n   154\t        id: ruby\n   155\t        with:\n   156\t          ruby-version: \"3.3.12\"\n   157\t          bundler-cache: true\n   158\t          working-directory: pipeline\n   159\t\n   160\t      - name: Install verifier dependencies\n   161\t        id: dependencies\n   162\t        run: python -m pip install --disable-pip-version-check --require-hashes --no-deps -r pipeline/requirements.txt\n   163\t\n   164\t      - name: Parse and fetch immutable source\n   165\t        id: prepare\n   166\t        env:\n   167\t          BUNDLE_GEMFILE: ${{ github.workspace }}/pipeline/Gemfile\n   168\t          PALOMAR_INPUTS: ${{ toJSON(inputs) }}\n   169\t        run: |\n   170\t          python - <<'PYTHON'\n   171\t          import json, os, pathlib\n   172\t          path = pathlib.Path(os.environ[\"RUNNER_TEMP\"], \"submission-inputs.json\")\n   173\t          path.write_text(json.dumps({\"inputs\": json.loads(os.environ[\"PALOMAR_INPUTS\"])}))\n   174\t          PYTHON\n   175\t          python pipeline/scripts/verify_submission.py prepare \\\n   176\t            --event \"$RUNNER_TEMP/submission-inputs.json\" \\\n   177\t            --work-dir \"$RUNNER_TEMP/palomar\" \\\n   178\t            --output \"$RUNNER_TEMP/mechanical-report.json\" \\\n   179\t            --licensee \"$(command -v bundle)\"\n   180\t\n   181\t      - name: Free disk space\n   182\t        id: disk\n   183\t        if: inputs.mode == 'full' && steps.prepare.outputs.ready == 'true'\n   184\t        uses: jlumbroso/free-disk-space@54081f138730dfa15788a46383842cd2f914a1be # v1.3.1\n   185\t        with:\n   186\t          tool-cache: false\n   187\t          android: true\n   188\t          dotnet: true\n   189\t          haskell: true\n   190\t          large-packages: false\n   191\t          docker-images: true\n   192\t          swap-storage: false\n   193\t\n   194\t      - name: Check palomar-standard-v1 runner capacity\n   195\t        id: capacity\n   196\t        if: inputs.mode == 'full' && steps.prepare.outputs.ready == 'true'\n   197\t        run: >-\n   198\t          python pipeline/scripts/verify_submission.py check-capacity\n   199\t          --disk-path \"$RUNNER_TEMP\" --output \"$RUNNER_TEMP/mechanical-report.json\"\n   200\t\n   201\t      - name: Install pinned elan\n   202\t        id: elan\n   203\t        if: inputs.mode == 'full' && steps.prepare.outputs.ready == 'true'\n   204\t        run: |\n   205\t          python3 pipeline/scripts/trusted_download.py \\\n   206\t            --url https://github.com/leanprover/elan/releases/download/v4.2.3/elan-x86_64-unknown-linux-gnu.tar.gz \\\n   207\t            --output \"$RUNNER_TEMP/elan.tar.gz\" \\\n   208\t            --sha256 df0b2b3a439961ffcbb3985214365ffe40f49bc871df04dff268c7d8e21ca8b2\n   209\t          mkdir \"$RUNNER_TEMP/elan\"\n   210\t          tar -xzf \"$RUNNER_TEMP/elan.tar.gz\" -C \"$RUNNER_TEMP/elan\"\n   211\t          \"$RUNNER_TEMP/elan/elan-init\" -y --no-modify-path --default-toolchain none\n   212\t          echo \"$HOME/.elan/bin\" >> \"$GITHUB_PATH\"\n   213\t\n   214\t      # The submitted toolchain judges the submission: its `lake comparator`,\n   215\t      # `leanexport`, `leanchecker` and bundled kernels. Nothing else is built.\n   216\t      - name: Install the submitted Lean toolchain\n   217\t        id: toolchain\n   218\t        if: inputs.mode == 'full' && steps.prepare.outputs.ready == 'true'\n   219\t        env:\n   220\t          SUBMISSION_TOOLCHAIN: ${{ steps.prepare.outputs.lean_toolchain }}\n   221\t        run: elan toolchain install \"$SUBMISSION_TOOLCHAIN\"\n   222\t\n   223\t      - name: Build pinned bubblewrap\n   224\t        id: bwrap\n   225\t        if: inputs.mode == 'full' && steps.prepare.outputs.ready == 'true'\n   226\t        run: |\n   227\t          sudo apt-get update -qq >/dev/null\n   228\t          sudo apt-get install -y -qq meson ninja-build libcap-dev pkg-config >/dev/null\n   229\t          echo \"PALOMAR_BWRAP=$(pipeline/scripts/install_bwrap.sh \"$RUNNER_TEMP/bwrap-bin\")\" >> \"$GITHUB_ENV\"\n   230\t\n   231\t      - name: Run lake comparator and challenge provenance audit\n   232\t        id: execute\n   233\t        if: inputs.mode == 'full' && steps.prepare.outputs.ready == 'true'\n   234\t        run: |\n   235\t          python pipeline/scripts/verify_submission.py execute \\\n   236\t            --work-dir \"$RUNNER_TEMP/palomar\" \\\n   237\t            --output \"$RUNNER_TEMP/mechanical-report.json\" \\\n   238\t            --bwrap \"$PALOMAR_BWRAP\" \\\n   239\t            --bwrap-source-tag v0.12.0 \\\n   240\t            --execution-budget-seconds \"${{ needs.profile.outputs.budget }}\" \\\n   241\t            --workflow-url \"${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\"\n   242\t\n   243\t      - name: Finalize interrupted mechanical report\n   244\t        if: always()\n   245\t        env:\n   246\t          PALOMAR_INPUTS: ${{ toJSON(inputs) }}\n   247\t          PALOMAR_STEPS: ${{ toJSON(steps) }}\n   248\t          PALOMAR_WORKFLOW_URL: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\n   249\t        run: python3 pipeline/scripts/workflow_report.py finalize --report \"$RUNNER_TEMP/mechanical-report.json\"\n   250\t\n   251\t      - name: Upload bounded mechanical report\n   252\t        id: upload1\n   253\t        continue-on-error: true\n   254\t        if: always()\n   255\t        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1\n   256\t        with:\n   257\t          name: ${{ inputs.mode == 'preflight' && 'preflight-report' || inputs.mode == 'correction' && 'correction-report' || 'mechanical-report' }}-${{ inputs.request_id }}\n   258\t          path: ${{ runner.temp }}/mechanical-report.json\n   259\t          if-no-files-found: error\n   260\t          retention-days: 90\n   261\t\n   262\t      - name: Wait before report upload retry 2\n   263\t        if: always() && steps.upload1.outcome == 'failure'\n   264\t        run: sleep 5\n   265\t\n   266\t      - name: Retry bounded mechanical report upload 2\n   267\t        id: upload2\n   268\t        continue-on-error: true\n   269\t        if: always() && steps.upload1.outcome == 'failure'\n   270\t        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1\n   271\t        with:\n   272\t          name: ${{ inputs.mode == 'preflight' && 'preflight-report' || inputs.mode == 'correction' && 'correction-report' || 'mechanical-report' }}-${{ inputs.request_id }}\n   273\t          path: ${{ runner.temp }}/mechanical-report.json\n   274\t          if-no-files-found: error\n   275\t          retention-days: 90\n   276\t          overwrite: true\n   277\t\n   278\t      - name: Wait before report upload retry 3\n   279\t        if: always() && steps.upload1.outcome == 'failure' && steps.upload2.outcome == 'failure'\n   280\t        run: sleep 20\n   281\t\n   282\t      - name: Retry bounded mechanical report upload 3\n   283\t        id: upload3\n   284\t        continue-on-error: true\n   285\t        if: always() && steps.upload1.outcome == 'failure' && steps.upload2.outcome == 'failure'\n   286\t        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1\n   287\t        with:\n   288\t          name: ${{ inputs.mode == 'preflight' && 'preflight-report' || inputs.mode == 'correction' && 'correction-report' || 'mechanical-report' }}-${{ inputs.request_id }}\n   289\t          path: ${{ runner.temp }}/mechanical-report.json\n   290\t          if-no-files-found: error\n   291\t          retention-days: 90\n   292\t          overwrite: true\n   293\t\n   294\t      - name: Fail the run when verification did not pass\n   295\t        if: always()\n   296\t        env:\n   297\t          PALOMAR_INPUTS: ${{ toJSON(inputs) }}\n   298\t          PALOMAR_STEPS: ${{ toJSON(steps) }}\n   299\t        run: python3 pipeline/scripts/workflow_report.py gate --report \"$RUNNER_TEMP/mechanical-report.json\"\n--- execution-profiles.json\n     1\t{\n     2\t  \"schema_version\": 1,\n     3\t  \"default\": \"palomar-namespace-16x32-v1\",\n     4\t  \"profiles\": {\n     5\t    \"palomar-namespace-16x32-v1\": {\n     6\t      \"runner\": {\n     7\t        \"provider\": \"namespace\",\n     8\t        \"label\": \"nscloud-ubuntu-24.04-amd64-16x32-with-features\",\n     9\t        \"labels\": [\n    10\t          \"nscloud-ubuntu-24.04-amd64-16x32-with-features\",\n    11\t          \"namespace-features:container.privileged=true\"\n    12\t        ],\n    13\t        \"architecture\": \"x86_64\"\n    14\t      },\n    15\t      \"limits\": {\n    16\t        \"minimum_host_memory_bytes\": 30064771072,\n    17\t        \"job_timeout_minutes\": 350,\n    18\t        \"execution_budget_seconds\": 19800\n    19\t      }\n    20\t    }\n    21\t  }\n    22\t}\n--- verification-profile.json\n     1\t{\n     2\t  \"schema_version\": 1,\n     3\t  \"id\": \"palomar-standard-v1\",\n     4\t  \"runner\": {\n     5\t    \"provider\": \"github-hosted\",\n     6\t    \"label\": \"ubuntu-24.04\",\n     7\t    \"architecture\": \"x86_64\"\n     8\t  },\n     9\t  \"limits\": {\n    10\t    \"job_timeout_minutes\": 350,\n    11\t    \"execution_budget_seconds\": 19800,\n    12\t    \"minimum_workspace_free_bytes\": 21474836480,\n    13\t    \"tasks_max\": 32768,\n    14\t    \"open_files_max\": 1048576,\n    15\t    \"file_size_max_bytes\": 1099511627776,\n    16\t    \"memory_high_percent\": 95,\n    17\t    \"memory_max_percent\": 98,\n    18\t    \"minimum_host_memory_bytes\": 15032385536\n    19\t  },\n    20\t  \"trusted_tools\": {\n    21\t    \"toolchain_floor\": \"v4.35.0-rc2\",\n    22\t    \"bwrap_source_tag\": \"v0.12.0\"\n    23\t  },\n    24\t  \"cache_policy\": \"fresh submitted .lake state; pinned Mathlib cache artifacts when available\"\n    25\t}\n--- scripts/verification_profile.py\n     1\t#!/usr/bin/env python3\n     2\t\"\"\"Load and validate Palomar's published verification resource policy.\"\"\"\n     3\t\n     4\tfrom __future__ import annotations\n     5\t\n     6\timport hashlib\n     7\timport json\n     8\timport os\n     9\timport platform\n    10\timport re\n    11\timport shutil\n    12\tfrom pathlib import Path\n    13\tfrom typing import Any\n    14\t\n    15\tROOT = Path(__file__).resolve().parent.parent\n    16\tPROFILE_PATH = ROOT / \"verification-profile.json\"\n    17\tCATALOGUE_PATH = ROOT / \"execution-profiles.json\"\n    18\t\n    19\t\n    20\tclass VerificationProfileError(RuntimeError):\n    21\t    pass\n    22\t\n    23\t\n    24\tHOSTED_PROFILE = \"palomar-standard-v1\"\n    25\tNAMESPACE_LABEL_RE = re.compile(r\"^nscloud-ubuntu-24\\.04-amd64-\\d+x\\d+-with-features$\")\n    26\tNAMESPACE_FEATURE_LABEL = \"namespace-features:container.privileged=true\"\n    27\tCATALOGUE_LIMITS = {\"minimum_host_memory_bytes\", \"job_timeout_minutes\", \"execution_budget_seconds\"}\n    28\t\n    29\t\n    30\tdef load_catalogue() -> dict[str, Any]:\n    31\t    \"\"\"The approved execution profiles beside the hosted one, validated by shape.\"\"\"\n    32\t    catalogue = json.loads(CATALOGUE_PATH.read_text(encoding=\"utf-8\"))\n    33\t    if (\n    34\t        not isinstance(catalogue, dict)\n    35\t        or catalogue.get(\"schema_version\") != 1\n    36\t        or not isinstance(catalogue.get(\"default\"), str)\n    37\t        or not isinstance(catalogue.get(\"profiles\"), dict)\n    38\t    ):\n    39\t        raise VerificationProfileError(\"approved execution profile catalogue is malformed\")\n    40\t    for identifier, selected in catalogue[\"profiles\"].items():\n    41\t        if not re.fullmatch(r\"palomar-[a-z0-9-]+-v\\d+\", identifier) or identifier == HOSTED_PROFILE:\n    42\t            raise VerificationProfileError(f\"execution profile id is malformed: {identifier}\")\n    43\t        runner = selected.get(\"runner\") if isinstance(selected, dict) else None\n    44\t        limits = selected.get(\"limits\") if isinstance(selected, dict) else None\n    45\t        if (\n    46\t            set(selected) != {\"runner\", \"limits\"}\n    47\t            or not isinstance(runner, dict)\n    48\t            or set(runner) != {\"provider\", \"label\", \"labels\", \"architecture\"}\n    49\t            or runner[\"provider\"] != \"namespace\"\n    50\t            or runner[\"architecture\"] != \"x86_64\"\n    51\t            or not NAMESPACE_LABEL_RE.fullmatch(str(runner[\"label\"]))\n    52\t            or runner[\"labels\"] != [runner[\"label\"], NAMESPACE_FEATURE_LABEL]\n    53\t            or not isinstance(limits, dict)\n    54\t            or set(limits) != CATALOGUE_LIMITS\n    55\t            or any(type(limits[name]) is not int or limits[name] <= 0 for name in CATALOGUE_LIMITS)\n    56\t            or limits[\"execution_budget_seconds\"] > limits[\"job_timeout_minutes\"] * 60\n    57\t        ):\n    58\t            raise VerificationProfileError(f\"approved execution profile is malformed: {identifier}\")\n    59\t    if catalogue[\"default\"] != HOSTED_PROFILE and catalogue[\"default\"] not in catalogue[\"profiles\"]:\n    60\t        raise VerificationProfileError(\"approved execution profile catalogue default is not approved\")\n    61\t    return catalogue\n    62\t\n    63\t\n    64\tdef default_profile_id() -> str:\n    65\t    return load_catalogue()[\"default\"]\n    66\t\n    67\t\n    68\tdef load_profile(identifier: str | None = None) -> dict[str, Any]:\n    69\t    identifier = identifier or os.environ.get(\"PALOMAR_EXECUTION_PROFILE\") or default_profile_id()\n    70\t    value = json.loads(PROFILE_PATH.read_text(encoding=\"utf-8\"))\n    71\t    if not isinstance(value, dict) or set(value) != {\n    72\t        \"schema_version\",\n    73\t        \"id\",\n    74\t        \"runner\",\n    75\t        \"limits\",\n    76\t        \"trusted_tools\",\n    77\t        \"cache_policy\",\n    78\t    }:\n    79\t        raise VerificationProfileError(\"verification profile has an invalid top-level shape\")\n    80\t    if value[\"schema_version\"] != 1 or value[\"id\"] != \"palomar-standard-v1\":\n    81\t        raise VerificationProfileError(\"verification profile identity is unsupported\")\n    82\t    runner = value[\"runner\"]\n    83\t    if not isinstance(runner, dict) or set(runner) != {\"provider\", \"label\", \"architecture\"}:\n    84\t        raise VerificationProfileError(\"verification profile runner is invalid\")\n    85\t    limits = value[\"limits\"]\n    86\t    expected_limits = {\n    87\t        \"job_timeout_minutes\",\n    88\t        \"execution_budget_seconds\",\n    89\t        \"memory_high_percent\",\n    90\t        \"memory_max_percent\",\n    91\t        \"minimum_workspace_free_bytes\",\n    92\t        \"tasks_max\",\n    93\t        \"open_files_max\",\n    94\t        \"file_size_max_bytes\",\n    95\t        \"minimum_host_memory_bytes\",\n    96\t    }\n    97\t    if not isinstance(limits, dict) or set(limits) != expected_limits:\n    98\t        raise VerificationProfileError(\"verification profile limits are invalid\")\n    99\t    if any(type(limits[name]) is not int or limits[name] <= 0 for name in expected_limits):\n   100\t        raise VerificationProfileError(\"verification profile limits must be positive integers\")\n   101\t    if not (limits[\"memory_high_percent\"] < limits[\"memory_max_percent\"] <= 100):\n   102\t        raise VerificationProfileError(\"memory_high_percent must be below memory_max_percent\")\n   103\t    if limits[\"execution_budget_seconds\"] > limits[\"job_timeout_minutes\"] * 60:\n   104\t        raise VerificationProfileError(\"execution budget exceeds the job timeout\")\n   105\t    # What judges a submission is the submitted toolchain itself (at or above\n   106\t    # the floor) and the bubblewrap release the trusted phase builds; the\n   107\t    # profile names both so the record's provenance and the policy agree.\n   108\t    tools = value[\"trusted_tools\"]\n   109\t    expected_tools = {\"toolchain_floor\", \"bwrap_source_tag\"}\n   110\t    if not isinstance(tools, dict) or set(tools) != expected_tools:\n   111\t        raise VerificationProfileError(\"verification profile trusted tools are invalid\")\n   112\t    if not all(isinstance(tools[name], str) for name in expected_tools):\n   113\t        raise VerificationProfileError(\"verification profile trusted tools must be strings\")\n   114\t    if not re.fullmatch(r\"v[0-9]+\\.[0-9]+\\.[0-9]+(?:-rc[0-9]+)?\", tools[\"toolchain_floor\"]):\n   115\t        raise VerificationProfileError(\"verification profile toolchain_floor is not a release tag\")\n   116\t    if not re.fullmatch(r\"v[0-9]+\\.[0-9]+\\.[0-9]+\", tools[\"bwrap_source_tag\"]):\n   117\t        raise VerificationProfileError(\"verification profile bwrap_source_tag is not a release tag\")\n   118\t    if identifier != HOSTED_PROFILE:\n   119\t        catalogue = load_catalogue()\n   120\t        selected = catalogue[\"profiles\"].get(identifier)\n   121\t        if not isinstance(selected, dict):\n   122\t            raise VerificationProfileError(\"execution profile is not approved\")\n   123\t        value[\"id\"] = identifier\n   124\t        value[\"runner\"] = selected[\"runner\"]\n   125\t        value[\"limits\"].update(selected[\"limits\"])\n   126\t    return value\n   127\t\n   128\t\n   129\tdef profile_digest(profile: dict[str, Any]) -> str:\n   130\t    return hashlib.sha256(json.dumps(profile, sort_keys=True, separators=(\",\", \":\")).encode()).hexdigest()\n   131\t\n   132\t\n   133\tdef cgroup_directories() -> list[Path]:\n   134\t    \"\"\"The process's cgroup-v2 ancestors, including a namespaced mount root.\"\"\"\n   135\t    root = Path(\"/sys/fs/cgroup\")\n   136\t    try:\n   137\t        relative = next(\n   138\t            line[3:] for line in Path(\"/proc/self/cgroup\").read_text().splitlines() if line.startswith(\"0::\")\n   139\t        )\n   140\t        if \"..\" in Path(relative).parts:\n   141\t            return [root]\n   142\t        leaf = root / relative.lstrip(\"/\")\n   143\t        return [leaf, *[parent for parent in leaf.parents if parent == root or root in parent.parents]]\n   144\t    except (OSError, StopIteration):\n   145\t        return [root]\n   146\t\n   147\t\n   148\tdef effective_memory_bytes() -> int:\n   149\t    limits = [host_memory_bytes()]\n   150\t    for directory in cgroup_directories():\n   151\t        try:\n   152\t            raw = (directory / \"memory.max\").read_text().strip()\n   153\t            if raw.isdigit():\n   154\t                limits.append(int(raw))\n   155\t        except OSError:\n   156\t            continue\n   157\t    return min(limits)\n   158\t\n   159\t\n   160\tdef effective_cpu_count() -> float:\n   161\t    cpus = float(len(os.sched_getaffinity(0)))\n   162\t    for directory in cgroup_directories():\n   163\t        try:\n   164\t            quota, period = (directory / \"cpu.max\").read_text().split()\n   165\t            if quota.isdigit() and int(period) > 0:\n   166\t                cpus = min(cpus, int(quota) / int(period))\n   167\t        except (OSError, ValueError):\n   168\t            continue\n   169\t    return cpus\n   170\t\n   171\t\n   172\tdef host_memory_bytes() -> int:\n   173\t    for line in Path(\"/proc/meminfo\").read_text(encoding=\"utf-8\").splitlines():\n   174\t        if line.startswith(\"MemTotal:\"):\n   175\t            return int(line.split()[1]) * 1024\n   176\t    raise VerificationProfileError(\"could not read host memory capacity\")\n   177\t\n   178\t\n   179\tdef check_host(profile: dict[str, Any], disk_path: Path) -> dict[str, int | float | str]:\n   180\t    runner = profile[\"runner\"]\n   181\t    limits = profile[\"limits\"]\n   182\t    architecture = platform.machine()\n   183\t    accepted_architectures = {\"x86_64\": {\"x86_64\", \"amd64\"}}\n   184\t    if architecture.lower() not in accepted_architectures.get(runner[\"architecture\"], set()):\n   185\t        raise VerificationProfileError(\n   186\t            f\"runner architecture {architecture!r} does not satisfy {runner['architecture']}\"\n   187\t        )\n   188\t    cpus = effective_cpu_count()\n   189\t    if profile[\"id\"] == \"palomar-namespace-16x32-v1\" and cpus < 16:\n   190\t        raise VerificationProfileError(f\"runner has {cpus} effective CPUs; Namespace profile requires 16\")\n   191\t    memory = effective_memory_bytes()\n   192\t    if memory < limits[\"minimum_host_memory_bytes\"]:\n   193\t        raise VerificationProfileError(\n   194\t            f\"runner has {memory} memory bytes; profile requires {limits['minimum_host_memory_bytes']}\"\n   195\t        )\n   196\t    workspace = shutil.disk_usage(disk_path).free\n   197\t    if workspace < limits[\"minimum_workspace_free_bytes\"]:\n   198\t        raise VerificationProfileError(\n   199\t            f\"runner has {workspace} free workspace bytes; profile requires \"\n   200\t            f\"{limits['minimum_workspace_free_bytes']}\"\n   201\t        )\n   202\t    return {\n   203\t        \"architecture\": architecture,\n   204\t        \"effective_cpus\": cpus,\n   205\t        \"memory_bytes\": memory,\n   206\t        \"workspace_free_bytes\": workspace,\n   207\t        \"memory_high_bytes\": memory * limits[\"memory_high_percent\"] // 100,\n   208\t        \"memory_max_bytes\": memory * limits[\"memory_max_percent\"] // 100,\n   209\t    }\n   210\t\n   211\t\n   212\tdef main() -> int:\n   213\t    import argparse\n   214\t\n   215\t    parser = argparse.ArgumentParser()\n   216\t    parser.add_argument(\"--disk-path\", type=Path)\n   217\t    parser.add_argument(\"--profile\", default=None)\n   218\t    parser.add_argument(\"--resolve\", action=\"store_true\")\n   219\t    args = parser.parse_args()\n   220\t    profile = load_profile(args.profile)\n   221\t    if args.resolve:\n   222\t        runner = profile[\"runner\"]\n   223\t        labels = runner.get(\"labels\", [runner[\"label\"]])\n   224\t        outputs = {\n   225\t            \"labels\": json.dumps(labels),\n   226\t            \"profile\": profile[\"id\"],\n   227\t            \"digest\": profile_digest(profile),\n   228\t            \"timeout\": str(profile[\"limits\"][\"job_timeout_minutes\"]),\n   229\t            # Rendering starts from an accepted submission whose build the\n   230\t            # budget already bounds; it gets the verification timeout plus a\n   231\t            # margin. Computed here because workflow expressions cannot add.\n   232\t            \"render_timeout\": str(profile[\"limits\"][\"job_timeout_minutes\"] + 10),\n   233\t            \"budget\": str(profile[\"limits\"][\"execution_budget_seconds\"]),\n   234\t        }\n   235\t        with open(os.environ[\"GITHUB_OUTPUT\"], \"a\") as handle:\n   236\t            for name, value in outputs.items():\n   237\t                handle.write(f\"{name}={value}\\n\")\n   238\t        return 0\n   239\t    if args.disk_path is None:\n   240\t        parser.error(\"--disk-path is required unless resolving a profile\")\n   241\t    observed = check_host(profile, args.disk_path)\n   242\t    print(json.dumps({\"profile\": profile[\"id\"], \"observed\": observed}, sort_keys=True))\n   243\t    return 0\n   244\t\n   245\t\n   246\tif __name__ == \"__main__\":\n   247\t    raise SystemExit(main())\n--- scripts/verify_submission.py\n     1\t#!/usr/bin/env python3\n     2\t\"\"\"Prepare and mechanically verify one Palomar submission.\"\"\"\n     3\t\n     4\tfrom __future__ import annotations\n     5\t\n     6\timport argparse\n     7\timport datetime as dt\n     8\timport hashlib\n     9\timport json\n    10\timport math\n    11\timport os\n    12\timport pathlib\n    13\timport re\n    14\timport secrets\n    15\timport shutil\n    16\timport socket\n    17\timport stat\n    18\timport subprocess\n    19\timport sys\n    20\timport tempfile\n    21\timport threading\n    22\timport time\n    23\timport tomllib\n    24\tfrom collections.abc import Callable\n    25\tfrom dataclasses import dataclass\n    26\tfrom pathlib import Path\n    27\tfrom typing import Any\n    28\tfrom urllib.error import HTTPError, URLError\n    29\tfrom urllib.parse import quote, urlparse\n    30\tfrom urllib.request import Request, urlopen\n    31\t\n    32\tROOT = Path(__file__).resolve().parent.parent\n    33\tif __package__ in {None, \"\"}:\n    34\t    sys.path.insert(0, str(ROOT))\n    35\t\n    36\tfrom scripts import (  # noqa: E402\n    37\t    seccomp_filter,\n    38\t    submission_contract,\n    39\t)\n    40\tfrom scripts.orcid_validation import validate_records as validate_orcid_records  # noqa: E402\n    41\tfrom scripts.source_requirements import inspect_lean_sources, lean_source_files  # noqa: E402\n    42\tfrom scripts.verification_errors import (  # noqa: E402\n    43\t    FormalizationValidationError,\n    44\t    VerificationError,\n    45\t)\n    46\tfrom scripts.verification_profile import (  # noqa: E402\n    47\t    PROFILE_PATH,\n    48\t    VerificationProfileError,\n    49\t    check_host,\n    50\t    effective_memory_bytes,\n    51\t    load_profile,\n    52\t    profile_digest,\n    53\t)\n    54\t\n    55\tMAX_SOURCE_BYTES = 500 * 1024 * 1024\n    56\tGIT_NO_AUTO_MAINTENANCE = (\"-c\", \"gc.auto=0\", \"-c\", \"maintenance.auto=false\")\n    57\tMAX_LICENSE_BYTES = 1024 * 1024\n    58\tMAX_CHALLENGE_BYTES = 100 * 1024\n    59\tMAX_CHALLENGE_LINES = 1000\n    60\tMAX_CONFIGURATION_BYTES = 1024 * 1024\n    61\tMAX_CORRECTION_BASELINE_BYTES = 2 * 1024 * 1024\n    62\tSTANDARD_AXIOMS = {\"propext\", \"Quot.sound\", \"Classical.choice\"}\n    63\t# The checkers `lake comparator` runs besides Lean's own kernel: the name the\n    64\t# protected configuration registers each under, and the binary the selected\n    65\t# toolchain bundles for it. They are the binaries `--paranoid` would run;\n    66\t# Palomar makes no kernel version choice of its own.\n    67\tPROTECTED_KERNELS = ((\"nanoda\", \"nanoda_bin\"), (\"con-ron\", \"con-ron\"))\n    68\t# The toolchain binaries a verification runs, each digested into the record.\n    69\tTOOLCHAIN_TOOLS = (\"lake\", \"lean\", \"leanexport\", \"leanchecker\", \"nanoda_bin\", \"con-ron\")\n    70\tBWRAP_SOURCE_TAG_RE = re.compile(r\"^v[0-9]+\\.[0-9]+\\.[0-9]+$\")\n    71\t# `lake comparator` exits 2 when it could not run at all and 1 both when it has\n    72\t# found against the submission and when a step of its own failed. What it\n    73\t# prints tells the two apart (Lake/Check/Compare.lean, Axioms.lean and\n    74\t# CLI/Check.lean at v4.35.0-rc2). No candidate code runs in the judge phase,\n    75\t# but the transcript quotes declaration names the submitter chose, so every\n    76\t# marker is anchored to the start of its line and the names are kept free of\n    77\t# control characters: a name cannot begin a line of its own.\n    78\tCOMPARATOR_VERDICT_RE = re.compile(\n    79\t    r\"^error: (?:\"\n    80\t    r\"Const not found in challenge|Const not found in solution|Constant not found in solution\"\n    81\t    r\"|Const does not match between challenge and target\"\n    82\t    r\"|Challenge and solution constant kind don't match\"\n    83\t    r\"|Challenge and solution theorem statement do not match\"\n    84\t    r\"|Challenge constant is not a definition|Solution constant is not a definition\"\n    85\t    r\"|Solution constant is not a theorem|Illegal axiom detected)\",\n    86\t    re.MULTILINE,\n    87\t)\n    88\t# `runExternalKernel` says \"rejected\" for every nonzero kernel exit, a crash\n    89\t# included, so a kernel's word alone is not a verdict. Lean's own kernel runs\n    90\t# last and is the arbiter: its rejection is the submission's; an independent\n    91\t# kernel failing while Lean's accepts is Palomar's to look at.\n    92\tCOMPARATOR_KERNEL_REJECTED_RE = re.compile(r\"^(?P<kernel>[^\\n]+) kernel rejected the solution$\", re.MULTILINE)\n    93\tCOMPARATOR_LEAN_KERNEL = \"Lean default\"\n    94\tCOMPARATOR_INFRASTRUCTURE_RE = re.compile(\n    95\t    r\"^(?:bwrap: |Error while interacting with |error: Error while interacting with )\", re.MULTILINE\n    96\t)\n    97\tCOMPARATOR_REQUIRED_KEYS = {\n    98\t    \"challenge_module\",\n    99\t    \"solution_module\",\n   100\t    \"theorem_names\",\n   101\t    \"permitted_axioms\",\n   102\t}\n   103\tCOMPARATOR_ALLOWED_KEYS = COMPARATOR_REQUIRED_KEYS | {\n   104\t    \"definition_names\",\n   105\t    \"enable_nanoda\",\n   106\t}\n   107\tCOMPILED_ARTIFACT_SUFFIXES = {\n   108\t    \".a\",\n   109\t    \".bc\",\n   110\t    \".dll\",\n   111\t    \".dylib\",\n   112\t    \".ilean\",\n   113\t    \".ir\",\n   114\t    \".o\",\n   115\t    \".obj\",\n   116\t    \".olean\",\n   117\t    \".so\",\n   118\t    \".trace\",\n   119\t}\n   120\t# The module system's sidecars are double-suffixed, so `Path.suffix` reports\n   121\t# `.private`/`.server` and the table above cannot match them on its own.\n   122\tCOMPILED_ARTIFACT_NAME_SUFFIXES = (\".olean.private\", \".olean.server\")\n   123\tMAX_STAGED_LAKE_METADATA_FILES = 512\n   124\tMAX_STAGED_LAKE_METADATA_BYTES = 8 * 1024**3\n   125\tSTAGED_LAKE_CONTROL_NAMES = {\n   126\t    \"lake-manifest.json\",\n   127\t    \"lakefile.ilean\",\n   128\t    \"lakefile.lean\",\n   129\t    \"lakefile.olean\",\n   130\t    \"lakefile.toml\",\n   131\t    \"lean-toolchain\",\n   132\t}\n   133\tSTAGED_LAKE_CONTROL_DIRECTORIES = {\"build\", \"config\", \"packages\"}\n   134\t# A Lean toolchain, as a comparable version. Release candidates sort before the\n   135\t# release they lead to, so v4.31.0-rc2 < v4.31.0, and anything that does not\n   136\t# parse is refused rather than guessed at.\n   137\tTOOLCHAIN_RE = re.compile(\n   138\t    r\"^leanprover/lean4:v(?P<major>[0-9]+)\\.(?P<minor>[0-9]+)\\.(?P<patch>[0-9]+)\"\n   139\t    r\"(?:-rc(?P<rc>[0-9]+))?$\"\n   140\t)\n   141\tVERSION_RE = re.compile(\n   142\t    r\"^v(?P<major>[0-9]+)\\.(?P<minor>[0-9]+)\\.(?P<patch>[0-9]+)\"\n   143\t    r\"(?:-rc(?P<rc>[0-9]+))?$\"\n   144\t)\n   145\t\n   146\t\n   147\tdef parse_lean_version(value: str, pattern: re.Pattern[str]) -> tuple[int, int, int, int, int]:\n   148\t    match = pattern.fullmatch(value.strip())\n   149\t    if not match:\n   150\t        raise VerificationError(\n   151\t            f\"unsupported Lean toolchain: {value!r}\", code=\"toolchain.invalid\"\n   152\t        )\n   153\t    rc = match.group(\"rc\")\n   154\t    # The fourth element orders a release candidate before its release.\n   155\t    return (\n   156\t        int(match.group(\"major\")),\n   157\t        int(match.group(\"minor\")),\n   158\t        int(match.group(\"patch\")),\n   159\t        0 if rc else 1,\n   160\t        int(rc) if rc else 0,\n   161\t    )\n   162\t\n   163\t\n   164\tdef toolchain_release_tag(toolchain: str) -> str:\n   165\t    \"\"\"The tag in Palomar's tooling repositories that matches this toolchain.\n   166\t\n   167\t    The version is derived rather than looked up in a table that has to be\n   168\t    edited for every release and is stale the moment it is not. Tool-specific\n   169\t    policy may subsequently fall back from a missing stable patch tag to the\n   170\t    release line's patch-zero tag.\n   171\t    \"\"\"\n   172\t    match = TOOLCHAIN_RE.fullmatch(toolchain.strip())\n   173\t    if not match:\n   174\t        raise VerificationError(f\"unsupported Lean toolchain: {toolchain!r}\")\n   175\t    return \"v\" + toolchain.strip().split(\":v\", 1)[1]\n   176\t\n   177\t\n   178\tdef supported_toolchain(toolchain: str) -> str:\n   179\t    \"\"\"Refuse a toolchain below the floor Palomar's tooling supports.\"\"\"\n   180\t    settings = json.loads((ROOT / \"toolchains.json\").read_text(encoding=\"utf-8\"))\n   181\t    if not isinstance(settings, dict) or set(settings) != {\"schema_version\", \"minimum\"}:\n   182\t        raise VerificationError(\n   183\t            \"toolchains.json must contain exactly schema_version and minimum\",\n   184\t            code=\"palomar.toolchain_policy_invalid\",\n   185\t            owner=\"palomar\",\n   186\t            next_action=\"Do not change the repository; Palomar must repair its toolchain policy.\",\n   187\t        )\n   188\t    if type(settings[\"schema_version\"]) is not int or settings[\"schema_version\"] != 2:\n   189\t        raise VerificationError(\n   190\t            \"toolchains.json does not use schema version 2\",\n   191\t            code=\"palomar.toolchain_policy_invalid\",\n   192\t            owner=\"palomar\",\n   193\t            next_action=\"Do not change the repository; Palomar must repair its toolchain policy.\",\n   194\t        )\n   195\t    minimum = settings.get(\"minimum\")\n   196\t    if not isinstance(minimum, str) or not VERSION_RE.fullmatch(minimum):\n   197\t        raise VerificationError(\n   198\t            \"toolchains.json does not record a valid minimum\",\n   199\t            code=\"palomar.toolchain_policy_invalid\",\n   200\t            owner=\"palomar\",\n   201\t            next_action=\"Do not change the repository; Palomar must repair its toolchain policy.\",\n   202\t        )\n   203\t    if parse_lean_version(toolchain, TOOLCHAIN_RE) < parse_lean_version(minimum, VERSION_RE):\n   204\t        raise VerificationError(\n   205\t            f\"Lean toolchain {toolchain} is older than the minimum Palomar supports ({minimum})\",\n   206\t            code=\"toolchain.unsupported\",\n   207\t        )\n   208\t    return toolchain_release_tag(toolchain)\n   209\t\n   210\t\n   211\tdef resolve_release_commit(repository: str, tag: str) -> str:\n   212\t    \"\"\"The commit a tooling release points at.\n   213\t\n   214\t    The tag is resolved once and the commit it named is recorded in the\n   215\t    mechanical report, so a record always says exactly which revision of\n   216\t    Palomar's own tooling checked it, whatever the tag says afterwards.\n   217\t    \"\"\"\n   218\t    proc = subprocess.run(\n   219\t        [\"git\", \"ls-remote\", f\"https://github.com/{repository}\", f\"refs/tags/{tag}^{{}}\",\n   220\t         f\"refs/tags/{tag}\"],\n   221\t        check=False,\n   222\t        capture_output=True,\n   223\t        text=True,\n   224\t        timeout=120,\n   225\t    )\n   226\t    if proc.returncode != 0:\n   227\t        raise VerificationError(\n   228\t            f\"could not read {repository} releases\",\n   229\t            code=\"provider.release_lookup_failed\",\n   230\t            owner=\"provider\",\n   231\t            next_action=\"Do not change the repository. Retry the same commit later.\",\n   232\t            retryable=True,\n   233\t        )\n   234\t    commits = {}\n   235\t    for line in proc.stdout.splitlines():\n   236\t        parts = line.split()\n   237\t        if len(parts) == 2 and submission_contract.SHA_RE.fullmatch(parts[0]):\n   238\t            commits[parts[1]] = parts[0]\n   239\t    # An annotated tag resolves through its peeled ref; prefer that.\n   240\t    commit = commits.get(f\"refs/tags/{tag}^{{}}\") or commits.get(f\"refs/tags/{tag}\")\n   241\t    if not commit:\n   242\t        raise VerificationError(\n   243\t            f\"{repository} has published no {tag} release\",\n   244\t            code=\"palomar.toolchain_release_missing\",\n   245\t            owner=\"palomar\",\n   246\t            next_action=(\n   247\t                \"Do not change the repository. Palomar must add support for this Lean release.\"\n   248\t            ),\n   249\t        )\n   250\t    return commit\n   251\t\n   252\t\n   253\tdef toolchain_commit(toolchain: str) -> str:\n   254\t    \"\"\"The lean4 commit the submitted toolchain's release tag names.\n   255\t\n   256\t    Every tool that judges the submission (`lake comparator`, `leanexport`,\n   257\t    `leanchecker` and the bundled kernels) ships in that release, so this one\n   258\t    commit is the provenance of all of them; the record carries it together\n   259\t    with the digests of the installed binaries.\n   260\t    \"\"\"\n   261\t    return resolve_release_commit(\"leanprover/lean4\", supported_toolchain(toolchain))\n   262\t\n   263\t\n   264\tLICENSE_FILE_RE = re.compile(\n   265\t    r\"^(?:licen[cs]e|copying|unlicense|ofl)(?:\\.(?:md|markdown|txt))?$\",\n   266\t    re.IGNORECASE,\n   267\t)\n   268\tMODULE_RE = re.compile(r\"^[A-Za-z_][A-Za-z0-9_']*(?:\\.[A-Za-z_][A-Za-z0-9_']*)*$\")\n   269\tOFFICIAL_REF_RE = re.compile(r\"^refs/heads/[A-Za-z0-9._/-]+$\")\n   270\tSANDBOX_ENVIRONMENT = (\n   271\t    \"PATH\",\n   272\t    \"HOME\",\n   273\t    \"TMPDIR\",\n   274\t    \"LANG\",\n   275\t    \"LC_ALL\",\n   276\t    \"LEAN_PATH\",\n   277\t    \"LEAN_SRC_PATH\",\n   278\t    \"LEAN_ABORT_ON_PANIC\",\n   279\t    \"GIT_CONFIG_GLOBAL\",\n   280\t    \"GIT_CONFIG_NOSYSTEM\",\n   281\t    \"GIT_TERMINAL_PROMPT\",\n   282\t    \"MATHLIB_CACHE_DIR\",\n   283\t    \"MATHLIB_CACHE_GET_URL\",\n   284\t    \"LAKE_PKG_URL_MAP\",\n   285\t    \"COMPARATOR_BWRAP\",\n   286\t    \"PALOMAR_PROTECTED_CHALLENGE_MODULE\",\n   287\t)\n   288\t\n   289\t\n   290\tclass LicenseValidationError(VerificationError):\n   291\t    \"\"\"The submitted repository does not satisfy the licence policy.\"\"\"\n   292\t\n   293\t    def __init__(self, message: str) -> None:\n   294\t        super().__init__(\n   295\t            message,\n   296\t            code=\"license.mismatch\",\n   297\t            field=\"project.license\",\n   298\t            repairable=True,\n   299\t            next_action=(\n   300\t                \"Make project.license agree with the repository license file, commit the \"\n   301\t                \"change, and make a new submission.\"\n   302\t            ),\n   303\t        )\n   304\t\n   305\t\n   306\tclass LicenseDetectorError(VerificationError):\n   307\t    \"\"\"The trusted SPDX detector failed rather than rejecting submitted terms.\"\"\"\n   308\t\n   309\t    def __init__(self, message: str) -> None:\n   310\t        super().__init__(\n   311\t            message,\n   312\t            code=\"palomar.license_detector_failed\",\n   313\t            owner=\"palomar\",\n   314\t            next_action=(\n   315\t                \"Do not change the repository. Retry the same commit later; report the \"\n   316\t                \"workflow URL if the problem recurs.\"\n   317\t            ),\n   318\t            retryable=True,\n   319\t        )\n   320\t\n   321\t\n   322\tclass ResourceExhausted(VerificationError):\n   323\t    \"\"\"The available worker could not complete a verification phase.\"\"\"\n   324\t\n   325\t    def __init__(self, message: str) -> None:\n   326\t        super().__init__(\n   327\t            message,\n   328\t            code=\"provider.resource_exhausted\",\n   329\t            owner=\"provider\",\n   330\t            next_action=(\n   331\t                \"Inspect the reported resource limit and build usage. If the workload repeatedly \"\n   332\t                \"exceeds the worker's capacity, reduce its resource use or arrange sufficient \"\n   333\t                \"capacity before retrying. Retry an unchanged commit only after addressing \"\n   334\t                \"the reported condition. Normal submission cooldowns still apply.\"\n   335\t            ),\n   336\t            retryable=True,\n   337\t        )\n   338\t\n   339\t\n   340\tDIAGNOSTICS_SCHEMA_VERSION = 1\n   341\tMAX_DIAGNOSTICS = 50\n   342\tPALOMAR_OWNED_STAGES = frozenset(\n   343\t    {\n   344\t        \"setup\",\n   345\t        \"confinement-initial\",\n   346\t        \"confinement-final\",\n   347\t        \"trusted-cache\",\n   348\t        \"trusted-roots\",\n   349\t        \"comparator-preflight\",\n   350\t        \"challenge-export\",\n   351\t        \"resource-exhausted\",\n   352\t    }\n   353\t)\n   354\t\n   355\t\n   356\tdef report_diagnostic(\n   357\t    report: dict[str, Any],\n   358\t    error: BaseException,\n   359\t    *,\n   360\t    stage: str | None = None,\n   361\t    owner: str | None = None,\n   362\t) -> None:\n   363\t    \"\"\"Append bounded public diagnostics without changing successful reports.\"\"\"\n   364\t    current_stage = stage or str(report.get(\"stage\") or \"unknown\")\n   365\t    if isinstance(error, FormalizationValidationError):\n   366\t        for issue in error.issues:\n   367\t            report_diagnostic(report, issue, stage=current_stage)\n   368\t        return\n   369\t    if isinstance(error, VerificationError):\n   370\t        diagnostic = error.diagnostic(current_stage)\n   371\t        reclassified_to_palomar = False\n   372\t        if owner is not None:\n   373\t            diagnostic[\"owner\"] = owner\n   374\t            reclassified_to_palomar = owner == \"palomar\" and error.owner == \"submitter\"\n   375\t        elif error.owner == \"submitter\" and current_stage in PALOMAR_OWNED_STAGES:\n   376\t            diagnostic[\"owner\"] = \"palomar\"\n   377\t            reclassified_to_palomar = True\n   378\t        if reclassified_to_palomar:\n   379\t            diagnostic[\"retryable\"] = True\n   380\t            diagnostic[\"repairable\"] = False\n   381\t            diagnostic[\"next_action\"] = (\n   382\t                \"Do not change the repository. Retry the same commit later; report the \"\n   383\t                \"workflow URL if the problem recurs.\"\n   384\t            )\n   385\t    else:\n   386\t        diagnostic = VerificationError(\n   387\t            \"Palomar could not complete this check.\",\n   388\t            code=\"palomar.internal_error\",\n   389\t            owner=\"palomar\",\n   390\t            next_action=(\n   391\t                \"Do not change the repository. Retry the same commit later; report the \"\n   392\t                \"workflow URL if the problem recurs.\"\n   393\t            ),\n   394\t            retryable=True,\n   395\t        ).diagnostic(current_stage)\n   396\t        diagnostic[\"explanation\"] = f\"{type(error).__name__}: {str(error)[:1_500]}\"\n   397\t    diagnostics = report.setdefault(\"diagnostics\", [])\n   398\t    if not isinstance(diagnostics, list) or len(diagnostics) >= MAX_DIAGNOSTICS:\n   399\t        return\n   400\t    key = (diagnostic[\"code\"], diagnostic[\"summary\"], diagnostic.get(\"field\"))\n   401\t    if any(\n   402\t        isinstance(item, dict)\n   403\t        and (item.get(\"code\"), item.get(\"summary\"), item.get(\"field\")) == key\n   404\t        for item in diagnostics\n   405\t    ):\n   406\t        return\n   407\t    report[\"diagnostics_schema_version\"] = DIAGNOSTICS_SCHEMA_VERSION\n   408\t    report[\"formalization_profile_version\"] = submission_contract.FORMALIZATION_PROFILE_VERSION\n   409\t    diagnostics.append(diagnostic)\n   410\t\n   411\t\n   412\tMAX_CAPTURE_BYTES = 8 * 1024 * 1024\n   413\tEXECUTION_BUDGET_SECONDS = 12 * 60 * 60\n   414\tVERIFICATION_PROFILE = load_profile()\n   415\tVERIFICATION_LIMITS = VERIFICATION_PROFILE[\"limits\"]\n   416\t_EXECUTION_DEADLINE: float | None = None\n   417\t_MONOTONIC = time.monotonic\n   418\t_WALL_TIME = time.time\n   419\t_RESOURCE_PHASE: str | None = None\n   420\t_RESOURCE_METRICS_PATH: Path | None = None\n   421\t_RESOURCE_DISK_PATH: Path | None = None\n   422\t\n   423\t\n   424\tdef permissive_resource_properties() -> tuple[str, ...]:\n   425\t    # Imported helpers also run inside the renderer's confined sanitizer, where\n   426\t    # /proc is deliberately hidden. Only the outer supervisor needs host capacity.\n   427\t    memory = effective_memory_bytes()\n   428\t    return (\n   429\t        f\"MemoryHigh={memory * VERIFICATION_LIMITS['memory_high_percent'] // 100}\",\n   430\t        f\"MemoryMax={memory * VERIFICATION_LIMITS['memory_max_percent'] // 100}\",\n   431\t        f\"TasksMax={VERIFICATION_LIMITS['tasks_max']}\",\n   432\t        f\"LimitNOFILE={VERIFICATION_LIMITS['open_files_max']}\",\n   433\t        f\"LimitFSIZE={VERIFICATION_LIMITS['file_size_max_bytes']}\",\n   434\t    )\n   435\t\n   436\t\n   437\tdef install_execution_deadline(\n   438\t    started_at_epoch: str | float | None = None,\n   439\t    budget_seconds: int = EXECUTION_BUDGET_SECONDS,\n   440\t) -> float | None:\n   441\t    \"\"\"Arm the shared deadline, including trusted CI setup time when supplied.\"\"\"\n   442\t    global _EXECUTION_DEADLINE\n   443\t\n   444\t    previous = _EXECUTION_DEADLINE\n   445\t    if budget_seconds < 60:\n   446\t        raise VerificationError(\"verification execution budget must be at least one minute\")\n   447\t    elapsed = 0.0\n   448\t    if started_at_epoch is not None:\n   449\t        try:\n   450\t            started_at = float(started_at_epoch)\n   451\t        except (TypeError, ValueError) as error:\n   452\t            raise VerificationError(\"invalid verification job start time\") from error\n   453\t        if not math.isfinite(started_at) or started_at <= 0:\n   454\t            raise VerificationError(\"invalid verification job start time\")\n   455\t        elapsed = max(0.0, _WALL_TIME() - started_at)\n   456\t    remaining = max(0.0, budget_seconds - elapsed)\n   457\t    _EXECUTION_DEADLINE = _MONOTONIC() + remaining\n   458\t    return previous\n   459\t\n   460\t\n   461\tdef _deadline_timeout(requested: int, command: list[str]) -> int:\n   462\t    \"\"\"Cap one phase by the verifier-wide wall-clock deadline when active.\"\"\"\n   463\t    if _EXECUTION_DEADLINE is None:\n   464\t        return requested\n   465\t    remaining = int(_EXECUTION_DEADLINE - _MONOTONIC())\n   466\t    if remaining < 1:\n   467\t        raise subprocess.TimeoutExpired(command, EXECUTION_BUDGET_SECONDS)\n   468\t    return min(requested, remaining)\n   469\t\n   470\t\n   471\tdef _bounded_stream_reader(stream: Any, destination: bytearray) -> None:\n   472\t    omitted = 0\n   473\t    try:\n   474\t        while True:\n   475\t            chunk = stream.read(64 * 1024)\n   476\t            if not chunk:\n   477\t                break\n   478\t            destination.extend(chunk)\n   479\t            if len(destination) > MAX_CAPTURE_BYTES:\n   480\t                excess = len(destination) - MAX_CAPTURE_BYTES\n   481\t                del destination[:excess]\n   482\t                omitted += excess\n   483\t    finally:\n   484\t        stream.close()\n   485\t    if omitted:\n   486\t        marker = f\"<output truncated; omitted {omitted} bytes>\\n\".encode()\n   487\t        destination[:0] = marker\n   488\t\n   489\t\n   490\tdef now() -> str:\n   491\t    return dt.datetime.now(dt.UTC).replace(microsecond=0).isoformat().replace(\"+00:00\", \"Z\")\n   492\t\n   493\t\n   494\tdef resource_metrics(path: Path) -> list[dict[str, Any]]:\n   495\t    if not path.is_file() or path.is_symlink() or path.stat().st_size > 1024 * 1024:\n   496\t        return []\n   497\t    records: list[dict[str, Any]] = []\n   498\t    for line in path.read_text(encoding=\"utf-8\").splitlines()[:1000]:\n   499\t        try:\n   500\t            value = json.loads(line)\n   501\t        except json.JSONDecodeError:\n   502\t            continue\n   503\t        if isinstance(value, dict):\n   504\t            records.append(value)\n   505\t    return records\n   506\t\n   507\t\n   508\tdef run(\n   509\t    command: list[str],\n   510\t    *,\n   511\t    cwd: Path | None = None,\n   512\t    env: dict[str, str] | None = None,\n   513\t    input_text: str | None = None,\n   514\t    timeout: int = 600,\n   515\t    check: bool = True,\n   516\t) -> subprocess.CompletedProcess[str]:\n   517\t    timeout = _deadline_timeout(timeout, command)\n   518\t    proc = subprocess.Popen(\n   519\t        command,\n   520\t        cwd=cwd,\n--- scripts/workflow_report.py\n     1\t\"\"\"Standard-library-only finalization of interrupted verification workflows.\n     2\t\n     3\tInputs and step outcomes are supplied by the trusted workflow, never by a\n     4\tcandidate file. This module can run even when dependency installation failed.\n     5\t\"\"\"\n     6\t\n     7\tfrom __future__ import annotations\n     8\t\n     9\timport argparse\n    10\timport datetime as dt\n    11\timport json\n    12\timport os\n    13\timport re\n    14\tfrom pathlib import Path\n    15\tfrom typing import Any\n    16\t\n    17\tMAX_REPORT_BYTES = 4 * 1024 * 1024\n    18\tSETUP_STEPS = (\n    19\t    \"checkout\",\n    20\t    \"python\",\n    21\t    \"ruby\",\n    22\t    \"dependencies\",\n    23\t    \"prepare\",\n    24\t    \"disk\",\n    25\t    \"capacity\",\n    26\t    \"elan\",\n    27\t    \"toolchain\",\n    28\t    \"bwrap\",\n    29\t    \"execute\",\n    30\t)\n    31\t\n    32\t\n    33\tdef finalize(report: Any, inputs: dict, steps: dict, *, workflow_url: str) -> dict:\n    34\t    repository = inputs.get(\"repository\", \"\")\n    35\t    commit = inputs.get(\"commit\", \"\")\n    36\t    identifier = inputs.get(\"request_id\", \"\")\n    37\t    if not re.fullmatch(r\"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+\", repository):\n    38\t        raise ValueError(\"invalid workflow repository\")\n    39\t    if not re.fullmatch(r\"[0-9a-f]{40}\", commit):\n    40\t        raise ValueError(\"invalid workflow commit\")\n    41\t    if not re.fullmatch(r\"[a-z0-9_-]{1,100}\", identifier):\n    42\t        raise ValueError(\"invalid workflow request identifier\")\n    43\t    bound = (\n    44\t        isinstance(report, dict)\n    45\t        # 1 until the verifier starts, 2 once it has (a correction report is\n    46\t        # 2 throughout); the finalizer binds either.\n    47\t        and report.get(\"schema_version\") in {1, 2}\n    48\t        and isinstance(report.get(\"source\"), dict)\n    49\t        and isinstance(report.get(\"submission\"), dict)\n    50\t        and report.get(\"source\", {}).get(\"repository\") == repository\n    51\t        and report.get(\"source\", {}).get(\"commit\") == commit\n    52\t        and report.get(\"submission\", {}).get(\"submission_id\") == identifier\n    53\t    )\n    54\t    failed = next(\n    55\t        (name for name in SETUP_STEPS if steps.get(name, {}).get(\"outcome\") in {\"failure\", \"cancelled\"}), None\n    56\t    )\n    57\t    terminal = (\n    58\t        bound\n    59\t        and report.get(\"status\") in {\"pass\", \"fail\", \"error\"}\n    60\t        and isinstance(report.get(\"errors\"), list)\n    61\t        and isinstance(report.get(\"diagnostics\", []), list)\n    62\t        and (report[\"status\"] == \"pass\" or bool(report[\"errors\"]))\n    63\t    )\n    64\t    preflight = (\n    65\t        bound\n    66\t        and inputs.get(\"mode\") == \"preflight\"\n    67\t        and report.get(\"status\") == \"pending\"\n    68\t        and steps.get(\"prepare\", {}).get(\"outputs\", {}).get(\"ready\") == \"true\"\n    69\t        and failed is None\n    70\t    )\n    71\t    if terminal or preflight:\n    72\t        # Preserve valid verifier diagnostics. A workflow step failing after a\n    73\t        # pass is still caught by the final job gate, not rewritten as a proof failure.\n    74\t        result = dict(report)\n    75\t    else:\n    76\t        malformed = report is not None and not bound\n    77\t        stage = failed or \"reporting\"\n    78\t        explanation = (\n    79\t            \"The mechanical report was malformed or did not match the workflow inputs.\"\n    80\t            if malformed\n    81\t            else f\"Verification did not finish; workflow step: {stage}.\"\n    82\t        )\n    83\t        result = {\n    84\t            **(report if bound else {}),\n    85\t            \"schema_version\": 1,\n    86\t            \"source\": {\"repository\": repository, \"commit\": commit},\n    87\t            \"submission\": {\"submission_id\": identifier},\n    88\t            \"status\": \"error\",\n    89\t            \"phase\": \"verification\",\n    90\t            \"stage\": stage,\n    91\t            \"checked_at\": dt.datetime.now(dt.UTC).strftime(\"%Y-%m-%dT%H:%M:%SZ\"),\n    92\t            \"errors\": [explanation],\n    93\t            \"warnings\": [],\n    94\t            \"diagnostics_schema_version\": 1,\n    95\t            \"diagnostics\": [\n    96\t                {\n    97\t                    \"code\": \"palomar.reporting_failed\" if malformed else \"palomar.workflow_incomplete\",\n    98\t                    \"stage\": stage,\n    99\t                    \"owner\": \"palomar\",\n   100\t                    \"summary\": explanation,\n   101\t                    \"explanation\": explanation,\n   102\t                    \"retryable\": True,\n   103\t                    \"repairable\": False,\n   104\t                    \"next_action\": \"No repository change is indicated. Report the workflow URL to Palomar.\",\n   105\t                }\n   106\t            ],\n   107\t        }\n   108\t        if bound:\n   109\t            result[\"last_active_stage\"] = report.get(\"stage\")\n   110\t        if inputs.get(\"mode\") in {\"preflight\", \"correction\"} or stage in {\n   111\t            \"checkout\",\n   112\t            \"python\",\n   113\t            \"ruby\",\n   114\t            \"dependencies\",\n   115\t            \"prepare\",\n   116\t        }:\n   117\t            result[\"phase\"] = \"preparation\"\n   118\t    result[\"workflow_url\"] = workflow_url\n   119\t    attempt = inputs.get(\"execution_attempt\", \"\")\n   120\t    if attempt:\n   121\t        if not re.fullmatch(r\"[0-9a-f]{32}\", attempt):\n   122\t            raise ValueError(\"invalid execution attempt\")\n   123\t        result[\"execution_attempt\"] = attempt\n   124\t    result[\"execution_profile\"] = inputs.get(\"execution_profile\") or resolved_profile(report)\n   125\t    return result\n   126\t\n   127\t\n   128\tdef resolved_profile(report: Any) -> str:\n   129\t    \"\"\"The profile the verifier ran under when the dispatch named none.\n   130\t\n   131\t    The verifier records it in the report's resource evidence; before that\n   132\t    evidence exists (a failure during setup) the answer is the catalogue's\n   133\t    default, which is what the workflow's profile job resolved.\n   134\t    \"\"\"\n   135\t    if isinstance(report, dict):\n   136\t        evidence = report.get(\"verification_profile\")\n   137\t        if isinstance(evidence, dict) and isinstance(evidence.get(\"id\"), str):\n   138\t            return evidence[\"id\"]\n   139\t    catalogue = json.loads(\n   140\t        (Path(__file__).resolve().parents[1] / \"execution-profiles.json\").read_text(encoding=\"utf-8\")\n   141\t    )\n   142\t    return str(catalogue[\"default\"])\n   143\t\n   144\t\n   145\tdef gate(report: dict, mode: str, ready: str, steps: dict) -> bool:\n   146\t    uploaded = any(steps.get(f\"upload{n}\", {}).get(\"outcome\") == \"success\" for n in (1, 2, 3))\n   147\t    failed = any(steps.get(name, {}).get(\"outcome\") in {\"failure\", \"cancelled\"} for name in SETUP_STEPS)\n   148\t    return (\n   149\t        uploaded\n   150\t        and not failed\n   151\t        and (\n   152\t            report.get(\"status\") == \"pass\"\n   153\t            or (mode == \"preflight\" and ready == \"true\" and report.get(\"status\") == \"pending\")\n   154\t        )\n   155\t    )\n   156\t\n   157\t\n   158\tdef main() -> int:\n   159\t    parser = argparse.ArgumentParser()\n   160\t    parser.add_argument(\"command\", choices=[\"finalize\", \"gate\"])\n   161\t    parser.add_argument(\"--report\", type=Path, required=True)\n   162\t    args = parser.parse_args()\n   163\t    inputs = json.loads(os.environ[\"PALOMAR_INPUTS\"])\n   164\t    steps = json.loads(os.environ[\"PALOMAR_STEPS\"])\n   165\t    report = None\n   166\t    try:\n   167\t        if args.report.is_symlink() or args.report.stat().st_size > MAX_REPORT_BYTES:\n   168\t            raise ValueError(\"unsafe report\")\n   169\t        report = json.loads(args.report.read_text(encoding=\"utf-8\"))\n   170\t    except (OSError, ValueError):\n   171\t        report = {} if args.report.exists() else None\n   172\t    if args.command == \"gate\":\n   173\t        ok = gate(\n   174\t            report or {},\n   175\t            inputs.get(\"mode\", \"full\"),\n   176\t            steps.get(\"prepare\", {}).get(\"outputs\", {}).get(\"ready\", \"\"),\n   177\t            steps,\n   178\t        )\n   179\t        if not ok:\n   180\t            print(\"::error::Verification or report delivery did not complete successfully\")\n   181\t            for error in (report or {}).get(\"errors\", []):\n   182\t                # Plain output, never interpolate candidate text into workflow commands.\n   183\t                print(json.dumps(str(error)[:2000]))\n   184\t        return 0 if ok else 1\n   185\t    result = finalize(report, inputs, steps, workflow_url=os.environ[\"PALOMAR_WORKFLOW_URL\"])\n   186\t    temporary = args.report.with_suffix(\".finalizing.json\")\n   187\t    with temporary.open(\"x\", encoding=\"utf-8\") as handle:\n   188\t        json.dump(result, handle, indent=2)\n   189\t        handle.write(\"\\n\")\n   190\t    temporary.replace(args.report)\n   191\t    return 0\n   192\t\n   193\t\n   194\tif __name__ == \"__main__\":\n   195\t    raise SystemExit(main())\n--- README.md\n     1\t# Palomar Submission\n     2\t\n     3\tMechanical verification for the Palomar registry.\n     4\t\n     5\t[**Submit a Lean-verified result →**](https://submit.palomar-registry.org)\n     6\t\n     7\tThe form asks for a public GitHub repository, an immutable commit, the\n     8\trepository-relative path of exactly one Comparator configuration, and a\n     9\tdeclaration of the submitter's relationship to the substantive formalization,\n    10\twhich is a claim about a person rather than about the code and is recorded\n    11\tpermanently. The repository itself carries the metadata. One configuration\n    12\tbecomes one Palomar entry; several configurations at the same repository and\n    13\tcommit are submitted separately, while one configuration selecting several\n    14\tdeclarations is verified and reviewed as a whole. CI then:\n    15\t\n    16\t1. validates the required root files and pinned commit, including parsing\n    17\t   `formalization.yaml` and enforcing Palomar's documented metadata minimum;\n    18\t2. installs the submitted Lean toolchain, which brings its own `lake\n    19\t   comparator`, `leanexport`, `leanchecker` and the bundled independent\n    20\t   kernels;\n    21\t3. compiles the Challenge against frozen, canonical Mathlib, Tau Ceti, or\n    22\t   CSLib output;\n    23\t4. computes the transitive source closure of the Challenge and verifies every\n    24\t   byte in it;\n    25\t5. builds the Solution under Palomar's own bubblewrap sandbox, exports the\n    26\t   canonical Challenge and the built Solution with the toolchain's exporter,\n    27\t   and has `lake comparator` judge the two exports, permitting at most the\n    28\t   three standard axioms and running the Solution through Lean's kernel and\n    29\t   the toolchain's bundled NanoDa and con-ron kernels;\n    30\t6. publishes a machine-readable report as a run artifact.\n    31\t\n    32\tVerification is dispatched by the submission server, not started from this\n    33\trepository. The run carries the submission identifier in its name, and the\n    34\treport leaves as an artifact rather than as a comment, so nothing here needs a\n    35\tcredential that can write anywhere.\n    36\t\n    37\tThe complete job is also a reusable workflow. A public repository may call it\n    38\tat an exact PalomarSubmission commit as a predictive mechanical preflight. It\n    39\truns the same verifier under the checked-in `palomar-standard-v1` profile, but\n    40\thas no Palomar state or credentials and is not itself a registry submission.\n    41\tEvery mechanical report records the profile id and digest.\n    42\t\n    43\tThe profile is workflow/report metadata, not a field in `comparator.json`.\n    44\tIt records the existing 95%/98% memory pressure/ceiling policy and the\n    45\t19,800-second production budget, without adding a CPU quota or changing swap\n    46\tpolicy. The capacity check records host memory, effective memory thresholds,\n    47\tand free workspace. A preflight can help detect an expensive failure before\n    48\tsubmission; it does not run Challenge rendering, editorial review, or registration.\n    49\tA later run can still differ because of host performance, cache availability,\n    50\tor a transient service failure. Normal submission cooldowns apply to all outcomes.\n    51\t\n    52\tPin the reusable workflow to a full commit, just as Palomar pins submitted\n    53\tsource:\n    54\t\n    55\t```yaml\n    56\tjobs:\n    57\t  palomar-preflight:\n    58\t    uses: PalomarRegistry/PalomarSubmission/.github/workflows/submission.yml@<full-commit>\n    59\t    with:\n    60\t      repository: ${{ github.repository }}\n    61\t      commit: ${{ github.sha }}\n    62\t      pipeline_commit: <same-full-commit-as-the-uses-reference>\n    63\t      request_id: preflight001\n    64\t      mode: full\n    65\t      options: '{\"comparator_config_path\":\"comparator.json\",\"authorization_relationship\":\"I am a responsible author or maintainer\"}'\n    66\t```\n    67\t\n    68\tKeep `pipeline_commit` equal to the workflow's `uses` SHA. This explicit input\n    69\tis for reusable callers only; server dispatches check out their workflow revision.\n    70\tThe caller asserts this pairing: the workflow validates the SHA format but\n    71\tcannot check that it matches `uses`. Third-party preflight reports are advisory.\n    72\tThe `inputs` context is materialized as the verifier's request for either trigger,\n    73\tso a caller's push or pull-request event cannot replace the supplied inputs.\n    74\t\n    75\tThe workflow has `preflight` and `full` modes. Both invoke\n    76\tthe same `verify_submission.py prepare` entry point; full verification merely\n    77\tcontinues into the expensive toolchain and proof steps after preparation says\n    78\tthe submission is ready. Their run names and artifact names are distinct so a\n    79\tpreflight result cannot be mistaken for mechanical verification. Failed reports\n    80\tcarry a bounded diagnostics-v1 list: every item names its owner, explanation,\n    81\tnext action, retryability, optional location, and—only for fields in\n    82\t[`formalization-profile.json`](formalization-profile.json)—whether a constrained\n    83\tmetadata repair may be offered.\n    84\t\n    85\tEvery report also labels its broad `phase` as `preparation` or `verification`.\n    86\tThat producer-owned classification lets downstream services keep preparation\n    87\tfailures actionable even when they are discovered during a full run.\n    88\t[`browser-preflight-policy.json`](browser-preflight-policy.json) publishes the\n    89\tbounded subset of preparation rules that the submission page can repeat at an\n    90\texact commit. It is advisory only: the workflow remains authoritative and\n    91\trepeats every check after submission. Consumers must fail open when the policy\n    92\tis unavailable or incompatible, and compare its complete contents before using\n    93\ta browser result to ask for confirmation. The file is generated: it is what\n    94\t`python -m scripts.browser_preflight_policy` projects from this repository's\n    95\tconstants, so change the constant and rerun that script with `--write` rather\n    96\tthan editing the document.\n    97\t\n    98\tFormalization profile 4 reports every missing or invalid mechanically required\n    99\tmetadata field separately and includes only safely reusable values from a\n   100\trecognized older shape. That lets the submission site explain and collect the\n   101\tcomplete correction in one form. It never guesses classifications,\n   102\tmaintainers, source relationships, review claims, or whether a repository is a\n   103\tthin wrapper; malformed or alias-bearing YAML remains a manual correction. The\n   104\tprofile carries the multiline `project.description` used as the public\n   105\tregistry abstract and structured `sources[].contributors` entries for\n   106\tnon-author source credits.\n   107\t\n   108\tThe proof project may use arbitrary pinned **public GitHub** Git dependencies\n   109\tat full 40-character commit SHAs. They build from source inside Palomar's fresh\n   110\tLake build directories. Submitted or substantive source repositories containing\n   111\tGit submodules are rejected. An inert submodule gitlink in a dependency is\n   112\tallowed because dependency submodules are never initialized or read; the exact\n   113\tgitlink is retained by the archive fork. Git LFS pointers are rejected everywhere, as are\n   114\tGit dependencies hosted anywhere other than GitHub. Palomar must be able to\n   115\tpreserve the complete source graph consumed by the accepted build in ordinary\n   116\tGit. The Challenge is compiled\n   117\tseparately without candidate Lake configuration, against only verified\n   118\tallowlisted dependencies; its protected module is published under an\n   119\tunpredictable per-run verifier-owned top-level namespace and is the statement\n   120\tPalomar exports for the comparator. The alias prevents a Challenge and Solution that share a\n   121\tsubmitted top-level namespace from capturing one another through Lean's\n   122\tpackage-prefix search. Common submitted prebuilt artifacts are rejected early,\n   123\tand no candidate build output can replace the protected statement or frozen\n   124\ttrusted dependency modules. Only this statement surface is restricted;\n   125\tarbitrary pinned dependencies remain available to the proof in `Solution.lean`.\n   126\tTau Ceti and CSLib imports are recorded as qualified trust surfaces; no other\n   127\tstatement dependency is accepted, including one from a project Palomar has\n   128\talready indexed.\n   129\t\n   130\tAn allowlisted root normally has to be an ancestor of its configured canonical\n   131\tbranch. A root may explicitly also accept exact semantic-version release tags\n   132\tfrom that same canonical repository. Mathlib uses this narrow exception because\n   133\tan official patch release can add a toolchain-bump commit to the previous\n   134\trelease while `master` has already advanced on the next release line. Arbitrary,\n   135\tnightly, and repository-local tags do not broaden the trusted history.\n   136\t\n   137\tIndependent kernel replay is a registry invariant, not a submitter option.\n   138\tThe optional `enable_nanoda` field in a submitted `comparator.json` is retained\n   139\tfor upstream compatibility but is deliberately non-authoritative: missing,\n   140\tfalse, or any other JSON value does not disable or block verification, and a\n   141\tsubmitted `external_kernels` is rejected. The trusted runner writes a separate\n   142\tprotected configuration that registers the toolchain's bundled NanoDa and\n   143\tcon-ron binaries as external kernels and passes that copy to `lake comparator`.\n   144\tThis avoids making submitters maintain a switch whose value Palomar must\n   145\toverride for every accepted result.\n   146\t\n   147\tAI review is not part of this repository's CI.\n   148\t[`PalomarReviewer`](https://github.com/PalomarRegistry/PalomarReviewer) runs it\n   149\tautomatically against the mechanical report of a passing run, using the prompts\n   150\tin [`PalomarPolicy`](https://github.com/PalomarRegistry/PalomarPolicy). No\n   151\tperson starts a review or approves its result.\n   152\t\n   153\t## Required source layout\n   154\t\n   155\tSee [`PalomarRegistry/PalomarPolicy`](https://github.com/PalomarRegistry/PalomarPolicy/blob/main/CONTRIBUTING.md).\n   156\tThe contract is:\n   157\t\n   158\t```text\n   159\tlean-toolchain            # in the project or the repository root\n   160\tlakefile.toml             #   or lakefile.lean, which also needs lake-manifest.json\n   161\tformalization.yaml\n   162\t<the Comparator configuration named by the submission>\n   163\t<its challenge_module and solution_module sources>\n   164\tLICENSE                   # repository root, and only there\n   165\t```\n   166\t\n   167\tOnly `formalization.yaml` is required under that exact name. The Challenge and\n   168\tSolution paths follow from `challenge_module` and `solution_module` in the\n   169\tComparator configuration, and the configuration's own path is the one the\n   170\tsubmission named, so none of the three is a fixed filename. The selected project\n   171\tneed not be the repository root either: `project_path` may name a subdirectory,\n   172\tand everything but the licence is resolved inside it.\n   173\t\n   174\tThe licence filename is case-insensitive and may instead use `LICENCE`,\n   175\t`COPYING`, `UNLICENSE`, or `OFL`, with an optional `.md`, `.markdown`, or\n   176\t`.txt` extension. Exactly one such regular root file is required. It must be\n   177\tnonempty UTF-8 text, match one standard SPDX licence mechanically, and agree\n   178\texactly with the SPDX identifier in `project.license`.\n   179\t\n   180\tCurrent metadata should declare `version: v0.4`; an omitted version follows the\n   181\tupstream dispatcher's v0.4 default. `formalization.yaml` must be valid YAML with\n   182\tone top-level mapping and a nonempty project name of at most 300 characters,\n   183\tplus nonempty description, authorship, license, classification,\n   184\tautomation-method, and review-status fields. Classification requires one to\n   185\teight official arXiv subject classes and permits up to eight distinct MSC2020\n   186\tcodes. Each project author may\n   187\tbe a name or a mapping with `name` and\n   188\toptional `github` login and `orcid`; ORCIDs may use the bare identifier or the\n   189\tcanonical `https://orcid.org/` URL and are stored in bare form by the registry.\n   190\tAn ORCID iD must not be included in a person's `name`; use a person mapping with\n   191\tseparate `name` and `orcid` fields instead. Preparation checks the iD's ISO 7064\n   192\tcheck digit and asks the public ORCID Registry whether that exact iD names a\n   193\tcurrent record. Palomar retains only the iD and the time of that check, not the\n   194\treturned profile. A missing or deactivated record is a metadata error; an\n   195\tunavailable registry is a retryable Palomar failure. The check establishes\n   196\tthat the record existed at that time. It does not authenticate the submitter,\n   197\testablish control of the ORCID record, or prove authorship. The current provenance\n   198\tcontract also requires a nonempty `project.responsible_maintainers` list and a\n   199\tnonempty `sources` list. The submitted repository is the substantive proof\n   200\tdevelopment by default, so ordinary submissions need no `repository` section.\n   201\tA thin wrapper must instead provide a pinned\n   202\t`repository.substantive_formalization`; the legacy explicit\n   203\t`repository.role: thin-wrapper` spelling remains accepted. Every source,\n   204\tincluding an `original-proof` entry, needs a\n   205\t`relationship`. An `original-proof` entry must use `relationship: other`;\n   206\tadditional sources accompanying an original result may use `background` or\n   207\t`other`. A `formalizes`, `adapts`, or `independently-proves` relationship instead\n   208\tdeclares the result source-based and therefore conflicts with `type:\n   209\toriginal-proof` anywhere in the list. Thus a result is original exactly when at\n   210\tleast one entry is `original-proof`, every such entry uses `other`, and every\n   211\tother relationship is `background` or `other`; it is source-based exactly when\n   212\tthere is no `original-proof` entry and at least one relationship is\n   213\t`formalizes`, `adapts`, or `independently-proves`. All other combinations fail.\n   214\tA supplied source `type` is a concise free-text description such as `article`,\n   215\t`paper`, `book`, `formalization`, or `web post`; it may be omitted except\n   216\twhere the exact value `original-proof` is the origin declaration. Invalid or\n   217\tmissing provenance fails mechanical verification with the field that needs\n   218\tchanging. Source `authors` are bibliographic authors. Optional\n   219\t`contributors` records non-author credits as mappings with a nonempty `name`\n   220\tand a free-form `role` of at most 200 characters.\n   221\t\n   222\t`project.description` is the public registry abstract for the formalization as\n   223\ta whole. It must be nonempty and should concisely identify the mathematical\n   224\tcontent and principal results. The browser displays it during preliminary\n   225\tchecks, and an authenticated submitter may ask Palomar to open a pull request\n   226\tchanging this field before full verification starts.\n   227\tNew files should not add a top-level `provenance` block: put maintainers under\n   228\t`project`, the optional thin-wrapper target under `repository`, and result origin\n   229\tin the source entries as above. For compatibility with older files, the verifier\n   230\tignores a top-level `provenance` block and accepts singular\n   231\t`project.responsible_maintainer` and `sources[].author` aliases; current plural\n   232\tfields take precedence when both spellings are present. Result origin is always\n   233\tderived from the current `sources` entries, so a `result_origin` value in an\n   234\tignored legacy block cannot override them. The exact mechanical minimum is\n   235\tenforced here; the fields' intended meaning and authoring conventions are\n   236\tdocumented in\n   237\t[`PalomarPolicy/CONTRIBUTING.md`](https://github.com/PalomarRegistry/PalomarPolicy/blob/main/CONTRIBUTING.md#3-write-formalizationyaml).\n   238\t\n   239\tThe checked-in identifier lists under [`taxonomies/`](taxonomies/) are snapshots\n   240\tof the official [arXiv taxonomy](https://arxiv.org/category_taxonomy) and\n   241\t[MSC2020](https://msc2020.org/). Their purpose is exact intake validation; the\n   242\teditorial AI separately checks whether the selected subjects are plausible for\n   243\tthe submitted result.\n   244\t\n   245\tThe prototype accepts public GitHub repositories and any released or RC Lean\n   246\ttoolchain at or above the minimum recorded in\n   247\t[`toolchains.json`](toolchains.json). There is no list of accepted versions:\n   248\ttooling revisions are derived from release tags, which is what a table of them\n   249\tkept getting wrong. Everything that judges a submission ships in the submitted\n   250\ttoolchain itself, so verification records the lean4 commit its release tag\n   251\tnames together with the digests of the installed binaries. Rendering selects\n   252\tthe exact Verso release tag; when a stable positive Lean patch release has no\n   253\texact Verso tag, Palomar uses that same major/minor release line's patch-zero\n   254\ttag and rebuilds the pinned source with the submission's exact Lean toolchain.\n   255\tRelease candidates never fall back. The resolved Verso commit is recorded in\n   256\tthe render report. The file is deliberately a closed record containing only\n   257\tits schema version and the minimum Lean release; it does not claim to configure\n   258\ttooling repositories that the verifier does not read from it.\n   259\t\n   260\t## Licensing\n   261\t\n   262\tPalomarSubmission's software is MIT-licensed. The vendored taxonomy data is a\n   263\tseparate work under the terms recorded in [`taxonomies/LICENSE.md`](taxonomies/LICENSE.md).\n   264\tSubmission licence validation covers the submitted repository snapshot only;\n   265\tcited papers, reused formalizations, and dependencies retain their own licences.\n   266\t\n   267\t## Security\n   268\t\n   269\tSubmission Lean is hostile input. The verification job has read-only repository\n   270\tpermissions and no credential in its environment, and its only output is a\n   271\tbounded JSON artifact, so there is no second job holding a write token to\n   272\tcompromise. See [`SECURITY.md`](SECURITY.md) before changing the workflow or\n   273\tverifier.\n   274\t\n   275\t## Code boundaries\n   276\t\n   277\t[`scripts/submission_contract.py`](scripts/submission_contract.py) owns the\n   278\tdispatch-input allowlist and envelope validation, GitHub repository\n   279\tnormalization, and the complete `formalization.yaml` contract.\n   280\t[`scripts/verify_submission.py`](scripts/verify_submission.py) applies the\n   281\tremaining per-field dispatch rules for the commit, existing id, and\n   282\tauthorization while it orchestrates checkout and verification. It does not\n   283\tcarry a second request or metadata parser or a compatibility entry point.\n   284\t\n   285\t## Development checks\n   286\t\n   287\tRepository Python files use the `E`, `F`, `I`, `UP`, and `B` Ruff rule families declared\n   288\tin [`pyproject.toml`](pyproject.toml). Install the single locked lint dependency\n   289\tand run the same check as CI with:\n   290\t\n   291\t```sh\n   292\tpython -m pip install --disable-pip-version-check --require-hashes \\\n   293\t  --no-deps --only-binary=:all: -r requirements-lint.txt\n   294\tpython -m ruff check .\n   295\t```\n   296\t\n   297\tThe verifier runtime dependency remains separately locked in\n   298\t[`requirements.txt`](requirements.txt); Ruff is not installed in verification\n   299\tor cold-build jobs.\n   300\t\n   301\tCI also rejects the wording of the retired intake mechanism, using the\n   302\tstdlib-only checker in\n   303\t[`.github/scripts/check_retired_intake_wording.py`](.github/scripts/check_retired_intake_wording.py).\n   304\tIt reads `SECURITY.md`, `README.md`, every Markdown file below `docs/`, and\n   305\tevery Python file below `scripts/`, including the ones sitting directly in it,\n   306\tand it takes an optional repository root so the tests can run it against a\n   307\tplanted file. It rejects a closed set of collocations, not the bare word\n   308\t\"issue\", which the tracker and private reporting still need. Anything it cannot\n   309\tread is a failure rather than a file it passes over, because a scan surface\n   310\tthat quietly shrinks is invisible in a passing run. Run it with:\n   311\t\n   312\t```sh\n   313\tpython .github/scripts/check_retired_intake_wording.py\n   314\t```\n   315\t\n   316\t## Lean source requirements\n   317\t\n   318\tEvery regular `.lean` source file in the submitted repository must use Lean's\n   319\tmodule system and contain at most **10,000 physical lines**. This includes\n   320\tChallenge, Solution, unused source files, generated certificates, contained\n   321\tprojects, and local path dependencies. Ordinary comments may precede the\n   322\t`module` header; module documentation belongs after it. Blank and comment lines\n   323\tcount. LF and CRLF each delimit one line; an unterminated final line counts,\n   324\tand a final newline does not add an empty line.\n   325\t\n   326\tLake configuration files named `lakefile.lean` are exempt from the module\n   327\theader requirement, but still have the 10,000-line cap. Files below `.git` or\n   328\t`.lake` are excluded; submitted `.lean` symbolic links are rejected so a link\n   329\tcannot hide an oversized source file. Separately declared\n   330\tsubstantive source repositories for thin wrappers receive the same checks.\n   331\tExternal pinned Git dependencies are outside this per-file limit; Lean still\n   332\tchecks their compatibility with the module system. The existing Challenge\n   333\tlimits of **1,000 lines and 100 KiB** also apply.\n   334\t\n   335\tPorting requires more than adding `module`: make the declarations needed by\n   336\tother modules public, use `public import` where the public interface needs an\n   337\timport, and expose definitions whose bodies clients need. See\n   338\t[Lean's modules and visibility reference](https://lean-lang.org/doc/reference/latest/Source-Files-and-Modules/#modules-and-visibility).\n   339\tRebuild and rerun Comparator after porting. Split oversized files into smaller\n   340\tmodules or reduce generated certificates; do not hide them in excluded paths.\n   341\t\n   342\tThe submission form and HTTPS intake check a bounded subset of the submitted\n   343\trepository at the exact commit and report incomplete scans explicitly. They do\n   344\tnot scan separately declared substantive repositories; preparation checks those.\n   345\tThe verifier scans the complete checkout before builds and confirms headers with Lean's parser before running\n   346\tsubmitted Lake code. Violations identify the file and require a corrected new\n   347\tcommit. These rules apply to new ordinary submissions and revisions; metadata\n   348\tcorrections retain their registered source and are not retroactively rejected.\n   349\t\n   350\tThe preparation report records `source_requirements` and aggregates file diagnostics\n   351\twith the other non-executing checks. `source.module_required`,\n   352\t`source.file_too_long`, `source.invalid_utf8`, `source.invalid_header`, and\n   353\t`source.symlink_not_allowed` are submitter failures, not retryable infrastructure\n   354\tfailures. Header confirmation uses Lean's fast import parser; full compilation\n   355\tcontinues to check the selected sources' complete syntax and line endings.\n   356\tExecution repeats the scan and batches\n   357\t`lean --deps-json` over all submitted source files before candidate Lake code\n   358\truns. `browser-preflight-policy.json` publishes the shared scope and line cap.\n","exit_code":0,"status":"completed"}}
