n    64\t  -- collapse compiler-generated companions into their parent inductive\n    65\t  let byTail := generatedTails.findSome? fun tail =>\n    66\t    if s.endsWith (\".\" ++ tail) then\n    67\t      let parent := (s.dropRight (tail.length + 1)).toName\n    68\t      match env.find? parent with\n    69\t      | some (.inductInfo _) => if closure.contains parent then some parent else none\n    70\t      | _ => none\n    71\t    else none\n    72\t  match byTail with\n    73\t  | some parent => parent\n    74\t  | none =>\n    75\t    -- collapse constructors, recursors, and projections likewise\n    76\t    let structural :=\n    77\t      match env.find? c with\n    78\t      | some (.ctorInfo v) => some v.induct\n    79\t      | some (.recInfo v) => v.all.head?\n    80\t      | _ =>\n    81\t        if (env.getProjectionFnInfo? c).isSome then some c.getPrefix\n    82\t        else none\n    83\t    match structural with\n    84\t    | some parent => if closure.contains parent then parent else c\n    85\t    | none => c\n    86\t\n    87\t/-- All local constants referenced by declaration `n`.\n    88\tMirrors comparator's `runForUsedConsts`: type + value (incl. theorem proofs)\n    89\t+ inductive ctors + recursor rule RHSs. -/\n    90\tdef refsOf (env : Environment) (definitionHoles : NameSet) (n : Name) : Array Name :=\n    91\t  match env.find? n with\n    92\t  | some ci =>\n    93\t    let fromType := ci.type.getUsedConstants\n    94\t    let fromValue :=\n    95\t      if definitionHoles.contains n then #[]\n    96\t      else match ci.value? (allowOpaque := true) with\n    97\t        | some v => v.getUsedConstants\n    98\t        | none => #[]\n    99\t    let extra : Array Name :=\n   100\t      match ci with\n   101\t      | .inductInfo v => v.ctors.toArray ++ v.all.toArray\n   102\t      | .ctorInfo v => #[v.induct]\n   103\t      | .recInfo v => v.rules.foldl (fun acc r => (acc.push r.ctor) ++ r.rhs.getUsedConstants) #[]\n   104\t      | _ => #[]\n   105\t    (fromType ++ fromValue ++ extra).filter (isLocal env)\n   106\t  | none => #[]\n   107\t\n   108\tpartial def collect (env : Environment) (definitionHoles : NameSet)\n   109\t    (queue : List Name) (seen : NameSet) : NameSet :=\n   110\t  match queue with\n   111\t  | [] => seen\n   112\t  | n :: rest =>\n   113\t    if seen.contains n || !isLocal env n then collect env definitionHoles rest seen\n   114\t    else\n   115\t      collect env definitionHoles\n   116\t        ((refsOf env definitionHoles n).toList ++ rest) (seen.insert n)\n   117\t\n   118\t/-- Target theorems closed when `MIPSTARRE_COMPARATOR_TARGETS` is unset. -/\n   119\tdef defaultTargets : List Name := [`MIPStarRE.LDT.Test.mainFormal]\n   120\t\n   121\t/-- Parse a comma-separated declaration list written by `challenge_config.py`. -/\n   122\tdef parseNames (s : String) : List Name :=\n   123\t  ((s.splitOn \",\").map String.trim).filterMap fun part =>\n   124\t    if part.isEmpty then none else some part.toName\n   125\t\n   126\tdef challengeTargets : IO (List Name) := do\n   127\t  match ← IO.getEnv \"MIPSTARRE_COMPARATOR_TARGETS\" with\n   128\t  | none => return defaultTargets\n   129\t  | some raw =>\n   130\t    let targets := parseNames raw\n   131\t    if targets.isEmpty then\n   132\t      throw (IO.userError \"MIPSTARRE_COMPARATOR_TARGETS is set but names no target\")\n   133\t    return targets\n   134\t\n   135\t/-- Definition values omitted from the generated Challenge. -/\n","exit_code":0,"status":"completed"}}
