9\t      U.IsPauliSPCC R\n    70\t          (MIPStarRE.QPBT.binaryRepresentation\n    71\t            (MIPStarRE.QPBT.fixedFieldModel R.q R.is_admissible_size)) ∧\n    72\t        U.toStrategy.value\n    73\t          (pauliGame R\n    74\t            (MIPStarRE.QPBT.binaryRepresentation\n    75\t              (MIPStarRE.QPBT.fixedFieldModel R.q R.is_admissible_size))\n    76\t            (MIPStarRE.QPBT.fixedBinTrace\n    77\t              (MIPStarRE.QPBT.fixedFieldModel R.q R.is_admissible_size))) = 1\n    78\t  have hstatement : statement (PauliParams.ofAdmissibleParams Q) := by\n    79\t    let R := PauliParams.ofAdmissibleParams Q\n    80\t    let fieldStatement : MIPStarRE.QPBT.FixedFieldModel Q.q → Prop := fun F =>\n    81\t      ∃ U : SymmetricPauliStrategy R F.K,\n    82\t        U.IsPauliSPCC R (MIPStarRE.QPBT.binaryRepresentation F) ∧\n    83\t          U.toStrategy.value\n    84\t            (pauliGame R (MIPStarRE.QPBT.binaryRepresentation F)\n    85\t              (MIPStarRE.QPBT.fixedBinTrace F)) = 1\n    86\t    have hfield : fieldStatement Q.model := by\n    87\t      refine ⟨S, ?_, ?_⟩\n    88\t      · exact (isPauliSPCC_iff_isSPCC Q S).2 hspccS\n    89\t      · rw [← pauliSymmetricGame_toGame Q]\n    90\t        exact hvalueS\n    91\t    have hmodel : Q.model =\n    92\t        MIPStarRE.QPBT.fixedFieldModel R.q R.is_admissible_size := by\n    93\t      rfl\n    94\t    have htransported := Eq.mp (congrArg fieldStatement hmodel) hfield\n    95\t    exact htransported\n    96\t  exact Eq.mp (congrArg statement hP) hstatement\n    97\t\n    98\tend\n    99\t\n   100\tend MIPStarRE.QPBT.Palomar\n     1\timport MIPStarRE.QPBT.Palomar.LowDegreeConsistencyBridge\n     2\t\n     3\t/-!\n     4\t# Compact low-degree soundness\n     5\t\n     6\tThis module transports the registered low-degree soundness theorem to the\n     7\tcompact Palomar game surface, preserving its constants, parameter domain,\n     8\tquantifier order, and three separate consistency conclusions.\n     9\t\n    10\t## References\n    11\t\n    12\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:413-440`,\n    13\tpaper `lem:ld-soundness`.\n    14\t-/\n    15\t\n    16\tnamespace MIPStarRE.QPBT.Palomar\n    17\t\n    18\tnoncomputable section\n    19\t\n    20\t/-- Quantum soundness of the simultaneous classical low-degree test, in the\n    21\tcompact Palomar presentation (paper `lem:ld-soundness`,\n    22\t`references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:413-440`). -/\n    23\ttheorem exists_ld_soundness :\n    24\t    ∃ a b : ℝ, 1 ≤ a ∧ 0 < b ∧ b ≤ 1 ∧\n    25\t      ∀ (P : LowDegreeParams) (ε : ℝ), 0 < ε →\n    26\t        ∀ S : LowDegreeStrategy P (MIPStarRE.QPBT.fixedFieldModel P.q\n    27\t            P.is_admissible_size).K,\n    28\t          S.IsProjective →\n    29\t          1 - ε ≤ S.value (lowDegreeGame P\n    30\t            (MIPStarRE.QPBT.binaryRepresentation\n    31\t              (MIPStarRE.QPBT.fixedFieldModel P.q\n    32\t                P.is_admissible_size))) →\n    33\t          ∃ GA : LowDegreePolynomialPOVM P\n    34\t              (MIPStarRE.QPBT.fixedFieldModel P.q\n    35\t                P.is_admissible_size).K S.ιA,\n    36\t            ∃ GB : LowDegreePolynomialPOVM P\n    37\t                (MIPStarRE.QPBT.fixedFieldModel P.q\n    38\t                  P.is_admissible_size).K S.ιB,\n    39\t              ldPointPolynomialDefect P S GB ≤\n    40\t                  deltaLd a b ε P.q P.m P.d P.k ∧\n    41\t                ldPolynomialPointDefect P S GA ≤\n    42\t                  deltaLd a b ε P.q P.m P.d P.k ∧\n    43\t                ldPolynomialPolynomialDefect P S GA GB ≤\n    44\t                  deltaLd a b ε P.q P.m P.d P.k := by\n    45\t  classical\n    46\t  obtain ⟨a, b, ha, hb, hb1, hsound⟩ := MIPStarRE.QPBT.exists_ld_soundness\n    47\t  refine ⟨a, b, ha, hb, hb1, ?_⟩\n    48\t  rintro ⟨q, m, d, k, hm, hd, hk, hq, hdvd⟩ ε hε S hprojective hvalue\n    49\t  le