220\t    config = json.loads(path.read_text(encoding=\"utf-8\"), object_pairs_hook=unique_comparator_object)\n  1221\t    expected_keys = {\n  1222\t        \"challenge_module\", \"solution_module\", \"theorem_names\", \"definition_names\",\n  1223\t        \"permitted_axioms\", \"external_kernels\",\n  1224\t    }\n  1225\t    if not isinstance(config, dict) or set(config) != expected_keys:\n  1226\t        raise VerificationError(\"protected Comparator configuration has the wrong keys\")\n  1227\t    if not re.fullmatch(r\"PalomarCanonical[0-9a-f]{24}\\.Challenge\", str(config[\"challenge_module\"])):\n  1228\t        raise VerificationError(\"protected Comparator configuration lost its Challenge alias\")\n  1229\t    module_source_suffix(config[\"solution_module\"])\n  1230\t    names = [*config[\"theorem_names\"], *config[\"definition_names\"]]\n  1231\t    if not config[\"theorem_names\"] or not all(valid_export_target_name(item) for item in names):\n  1232\t        raise VerificationError(\"protected Comparator configuration names invalid declarations\")\n  1233\t    if not set(config[\"permitted_axioms\"]) <= STANDARD_AXIOMS:\n  1234\t        raise VerificationError(\"protected Comparator configuration permits a non-standard axiom\")\n  1235\t    if config[\"external_kernels\"] != {name: list(argv) for name, argv in kernels.items()}:\n  1236\t        raise VerificationError(\"protected Comparator configuration names the wrong kernels\")\n  1237\t    for name, argv in config[\"external_kernels\"].items():\n  1238\t        if not re.fullmatch(r\"[a-z][a-z0-9-]{0,31}\", name):\n  1239\t            raise VerificationError(f\"protected Comparator kernel name is invalid: {name}\")\n  1240\t        if not argv or not all(isinstance(item, str) and item for item in argv):\n  1241\t            raise VerificationError(f\"protected Comparator kernel {name} has an invalid command\")\n  1242\t        if not Path(argv[0]).is_absolute():\n  1243\t            raise VerificationError(f\"protected Comparator kernel {name} is not an absolute path\")\n  1244\t    return config\n  1245\t\n  1246\t\n  1247\tdef prepare(args: argparse.Namespace) -> int:\n  1248\t    global _EXECUTION_DEADLINE\n  1249\t\n  1250\t    output = Path(args.output).resolve()\n  4630\t    Challenge that imports `Init` by hand is therefore not credited with it,\n  4631\t    which costs nothing that a reviewer reads.\n  4632\t    \"\"\"\n  4633\t    lines = [line for line in stdout.splitlines() if line.strip()]\n  4634\t    try:\n  4635\t        payload = json.loads(lines[-1])\n  4636\t    except (IndexError, json.JSONDecodeError) as error:\n  4637\t        raise VerificationError(\"Lean did not report a parsable header\") from error\n  4638\t    entries = payload.get(\"imports\") if isinstance(payload, dict) else None\n  4639\t    if not isinstance(entries, list) or len(entries) != 1 or not isinstance(entries[0], dict):\n  4640\t        raise VerificationError(\"Lean reported no single header\")\n  4641\t    reported = entries[0]\n  4642\t    errors = reported.get(\"errors\") or []\n  4643\t    if errors:\n  4644\t        raise VerificationError(f\"Lean rejected the header: {str(errors[0])[:500]}\")\n  4645\t    result = reported.get(\"result\")\n  4646\t    if not isinstance(result, dict) or not isinstance(result.get(\"isModule\"), bool):\n  4647\t        raise VerificationError(\"Lean did not report whether the source is a module\")\n  4648\t    reported_imports = result.get(\"imports\")\n  4649\t    if not isinstance(reported_imports, list):\n  4650\t        raise VerificationError(\"Lean did not report the header imports\")\n  4651\t    modules: list[str] = []\n  4652\t    for entry in reported_imports:\n  4653\t        if not isinstance(entry, dict) or not isinstance(entry.get(\"module\"), str):\n  4654\t            raise VerificationError(\"Lean reported an unreadable header import\")\n  4655\t        module = entry[\"module\"]\n  4656\t        if module != \"Init\":\n  4657\t            modules.append(module)\n  4658\t    return LeanHeader(is_module=result[\"isModule\"], imports=tuple(sorted(set(modules))))\n  4659\t\n  4660\t\n  4661\tdef lean_header(\n  4662\t    source: Path,\n  4663\t    *,\n  4664\t    lean_source: Path,\n  4665\t    lean: Path,\n  4666\t    environment: dict[str, str],\n  4667\t    writable_directories: list[Path],\n  4668\t    readable_paths: list[Path],\n  4669\t    executable_paths: list[Path],\n  4670\t    tools: dict[Path, str],\n  4671\t) -> LeanHeader:\n  4672\t    \"\"\"Ask Lean to read a source header.\n  4673\t\n  4674\t    ``--deps-json`` runs the compiler's own parser, the one Lake uses to decide\n  4675\t    which artifacts a module produces and which modules it imports, so\n  4676\t    Palomar's reading cannot drift from Lean's. The header is parsed, never\n  4677\t    elaborated, so this reads the candidate's source without running it.\n  4678\t    \"\"\"\n  4679\t    proc = sandboxed_run(\n  4680\t        [str(lean), \"--deps-json\", str(lean_source)],\n  4681\t        cwd=source,\n  4682\t        environment=environment,\n  4683\t        writable_directories=writable_directories,\n  4684\t        readable_paths=readable_paths,\n  4685\t        executable_paths=executable_paths,\n  4686\t        tools=tools,\n  4687\t    )\n  4688\t    return parse_lean_header(proc.stdout)\n  4689\t\n  4690\t\n  4691\tdef confirm_source_modules(\n  4692\t    checkout: Path, *, source: Path, lean: Path, environment: dict[str, str],\n  4693\t    writable_directories: list[Path], readable_paths: list[Path],\n  4694\t    executable_paths: list[Path], tools: dict[Path, str],\n  4695\t) -> None:\n  4696\t    \"\"\"Confirm every submitted header with Lean, before candidate Lake code runs.\n  4697\t\n  4698\t    --deps-json only parses headers, including unused sources; it never imports\n  4699\t    or elaborates the candidate. Batch requests bound argv size and avoid a\n  4700\t    separate sandbox setup per