relative, line=1,\n  4732\t                )\n  4733\t\n  4734\t\n  4735\tdef lean_source_dependencies(\n  4736\t    source: Path,\n  4737\t    *,\n  4738\t    challenge_source: Path,\n  4739\t    lean: Path,\n  4740\t    environment: dict[str, str],\n  4741\t    writable_directories: list[Path],\n  4742\t    readable_paths: list[Path],\n  4743\t    executable_paths: list[Path],\n  4744\t    tools: dict[Path, str],\n  4745\t) -> list[Path]:\n  4746\t    proc = sandboxed_run(\n  4747\t        [str(lean), \"--src-deps\", str(challenge_source)],\n  4748\t        cwd=source,\n  4749\t        environment=environment,\n  4750\t        writable_directories=writable_directories,\n  5010\t                \"Do not change the repository. Palomar must add support for this Lean release.\"\n  5011\t            ),\n  5012\t        )\n  5013\t    return {name: path.resolve(strict=True) for name, path in tools.items()}\n  5014\t\n  5015\t\n  5016\tdef tool_digests(tools: dict[str, Path], bwrap: Path) -> dict[str, str]:\n  5017\t    \"\"\"The sha256 of every binary that judged the submission, by name.\"\"\"\n  5018\t    return {**{name: sha256(path) for name, path in tools.items()}, \"bwrap\": sha256(bwrap)}\n  5019\t\n  5020\t\n  5021\tdef protected_kernels(tools: dict[str, Path]) -> dict[str, list[str]]:\n  5022\t    \"\"\"The external kernels the protected configuration registers, by name.\"\"\"\n  5023\t    return {name: [str(tools[binary])] for name, binary in PROTECTED_KERNELS}\n  5024\t\n  5025\t\n  5026\tdef primitive_targets(lean_prefix: Path) -> list[str]:\n  5027\t    \"\"\"The kernel-builtin constants `lake comparator` exports beside the declarations.\n  5028\t\n  5029\t    `compareAt` seeds its walk with them, and an export that lacks one fails a\n  5030\t    valid proof, so the list is read from the selected toolchain's own copy of\n  5031\t    `Lake/CLI/Check.lean` rather than duplicated here, where it would drift. A\n  5032\t    toolchain whose copy does not have the expected shape is refused.\n  5033\t    \"\"\"\n  5034\t    source = lean_prefix / \"src\" / \"lean\" / \"lake\" / \"Lake\" / \"CLI\" / \"Check.lean\"\n  5035\t    refusal = VerificationError(\n  5036\t        \"the selected Lean toolchain's lake comparator has an unrecognised export target list\",\n  5037\t        code=\"palomar.toolchain_unrecognised\",\n  5038\t        owner=\"palomar\",\n  5039\t        next_action=\"Do not change the repository. Palomar must add support for this Lean release.\",\n  5040\t    )\n  5041\t    try:\n  5042\t        text = source.read_text(encoding=\"utf-8\")\n  5043\t    except OSError as error:\n  5044\t        raise refusal from error\n  5045\t    match = re.search(\n  5046\t        r\"^def primitiveTargets[^\\n]*\\n(?P<body>.*?)^def \", text, re.MULTILINE | re.DOTALL\n  5047\t    )\n  5048\t    if match is None:\n  5049\t        raise refusal\n  5050\t    # Strip comments (`-- ``Nat.zero,` is a commented-out entry, not an entry),\n  5051\t    # then accept exactly one literal array of quoted names and nothing else:\n  5052\t    # a list assembled any other way would be read only in part.\n  5053\t    body = re.sub(r\"/-.*?-/\", \"\", match.group(\"body\"), flags=re.DOTALL)\n  5054\t    body = \"\\n\".join(line.split(\"--\", 1)[0] for line in body.splitlines())\n  5055\t    literal = re.fullmatch(r\"\\s*return\\s*#\\[(?P<items>[^\\[\\]]*)\\]\\s*\", body)\n  5056\t    if literal is None:\n  5057\t        raise refusal\n  5058\t    names: list[str] = []\n  5059\t    for item in literal.group(\"items\").split(\",\"):\n  5060\t        item = item.strip()\n  5061\t        if not item:\n  5062\t            continue\n  5063\t        name = re.fullmatch(r\"``([A-Za-z_][A-Za-z0-9_'.]*)\", item)\n  5064\t        if name is None:\n  5065\t            raise refusal\n  5066\t        names.append(name.group(1))\n  5067\t    if not names or len(set(names)) != len(names):\n  5068\t        raise refusal\n  5069\t    return names\n  5070\t\n  5071\t\n  5072\tdef comparator_export_targets(config: dict[str, Any], primitives: list[str]) -> list[str]:\n  5073\t    \"\"\"The declarations both exports carry, in the order `compareIt` asks for them.\"\"\"\n  5074\t    axioms = list(config[\"permitted_axioms\"])\n  5075\t    builtin = [\"Quot\", \"Quot.mk\", \"Quot.lift\", \"Quot.ind\"] if \"Quot.sound\" in axioms else []\n  5076\t    return [\n  5077\t        *builtin,\n  5078\t        *config[\"theorem_names\"],\n  5079\t        *axioms,\n  5080\t        *primitives,\n  5081\t        *config.get(\"definition_names\", []),\n  5082\t    ]\n  5083\t\n  5084\t\n  5085\tdef export_module(\n  5086\t    module: str,\n  5087\t    targets: list[str],\n  5088\t    *,\n  5089\t    output: Path,\n  5090\t    leanexport: Path,\n  5091\t    cwd: Path,\n  5092\t    environment: dict[str, str],\n  5093\t    readable_paths: list[Path],\n  5094\t    executable_paths: list[Path],\n  5095\t    tools: dict[Path, str],\n","exit_code":0,"status":"completed"}}
